```go
package main

import (
	"container/list"
	"errors"
	"sync"
)

// 缓存结构体，包含双向链表和哈希表
type Cache struct {
	capacity int          // 缓存容量限制
	ll       *list.List    // 双向链表
	cache    map[string]*list.Element
	mu       sync.Mutex    // 读写锁
}

// 节点数据结构
type Node struct {
	Key   string // 键
	Value interface{} // 值
}

// NewCache 创建一个新的 Cache 实例
func NewCache(capacity int) *Cache {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	return &Cache{
		capacity: capacity,
		ll:       list.New(),
		cache:    make(map[string]*list.Element, capacity), // 预分配空间以提高性能
	}
}

// Get 获取缓存中的值，同时将该节点移动到链表头部（最近使用）
func (c *Cache) Get(key string) (interface{}, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	element, found := c.cache[key]
	if !found {
		return nil, false
	}
	c.ll.MoveToFront(element)
	return element.Value.(*Node).Value, true
}

// Set 设置缓存值，如果已达容量则先淘汰最久未使用的节点
func (c *Cache) Set(key string, value interface{}) error {
	node := &Node{Key: key, Value: value}
	c.mu.Lock()
	defer c.mu.Unlock()

	// 如果已存在，则更新值并移动到头部
	if element, found := c.cache[key]; found {
		c.ll.MoveToFront(element)
		element.Value = node
		return nil
	}

	// 如果超出容量，则淘汰最久未使用节点
	if c.ll.Len() >= c.capacity {
		last := c.ll.Back()
		c.ll.Remove(last)
		delete(c.cache, last.Value.(*Node).Key)
	}

	// 将新节点插入链表头部，并更新哈希表
	element := c.ll.PushFront(node)
	c.cache[key] = element
	return nil
}

// Del 删除指定键的缓存项
func (c *Cache) Del(key string) error {
	c.mu.Lock()
	defer c.mu.Unlock()

	element, found := c.cache[key]
	if !found {
		return errors.New("key not found")
	}
	c.ll.Remove(element)
	delete(c.cache, key)
	return nil
}

// Len 返回缓存中元素的数量
func (c *Cache) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.ll.Len()
}

