在 Go 语言中实现一个带有 LRU（Least Recently Used）淘汰策略的缓存，可以使用 `sync.Mutex` 来保证线程安全，并结合双向链表和哈希表来高效地管理元素。下面是一个简单的示例：

```go
package main

import (
	"fmt"
	"sync"
)

// Node 定义双向链表节点
type Node struct {
	key, value int
	prev, next *Node
}

// LRUCache 实现 LRU 缓存
type LRUCache struct {
	cache     map[int]*Node // 哈希表用于快速查找
	capacity  int           // 最大容量
	head      *Node         // 双向链表头结点（最近使用的）
	tail      *Node         // 双向链表尾结点（最久未使用的）
	mutex     sync.RWMutex  // 读写锁，确保并发安全
}

// NewLRUCache 创建一个新的 LRU 缓存实例
func NewLRUCache(capacity int) *LRUCache {
	l := &LRUCache{
		cache:    make(map[int]*Node),
		capacity: capacity,
	}
	// 初始化双向链表的哨兵节点
	l.head = &Node{}
	l.tail = &Node{}
	l.head.next = l.tail
	l.tail.prev = l.head
	return l
}

// Get 获取缓存中的值
func (l *LRUCache) Get(key int) (int, bool) {
	l.mutex.RLock()
	defer l.mutex.RUnlock()

	if node, found := l.cache[key]; found {
		// 将访问的节点移动到头部（最近使用）
		l.moveToHead(node)
		return node.value, true
	}
	return 0, false
}

// Set 设置缓存值
func (l *LRUCache) Set(key, value int) {
	l.mutex.Lock()
	defer l.mutex.Unlock()

	if node, found := l.cache[key]; found {
		// 更新已存在的节点
		node.value = value
		l.moveToHead(node)
	} else {
		// 创建新节点
		newNode := &Node{key: key, value: value}
		l.addToHead(newNode)
		l.cache[key] = newNode

		// 如果超过容量，则删除最久未使用的节点
		if len(l.cache) > l.capacity {
			deleteNode := l.removeTail()
			delete(l.cache, deleteNode.key)
		}
	}
}

// moveToHead 将节点移动到双向链表头部
func (l *LRUCache) moveToHead(node *Node) {
	l.removeNode(node)
	l.addToHead(node)
}

// addToHead 在双向链表头部添加节点
func (l *LRUCache) addToHead(node *Node) {
	node.prev = l.head
	node.next = l.head.next
	l.head.next.prev = node
	l.head.next = node
}

// removeNode 从双向链表中移除节点
func (l *LRUCache) removeNode(node *Node) {
	node.prev.next = node.next
	node.next.prev = node.prev
}

// removeTail 从双向链表尾部移除节点并返回该节点
func (l *LRUCache) removeTail() *Node {
	node := l.tail.prev
	l.removeNode(node)
	return node
}

func main() {
	cache := NewLRUCache(2)
	cache.Set(1, 1)
	cache.Set(2, 2)
	fmt.Println(cache.Get(1)) // 输出: 1, true

	cache.Set(3, 3) // 这将使键为 2 的条目被踢出
	fmt.Println(cache.Get(2)) // 输出: 0, false

	cache.Set(4, 4) // 这将使键为 1 的条目被踢出
	fmt.Println(cache.Get(1)) // 输出: 0, false
	fmt.Println(cache.Get(3)) // 输出: 3, true
	fmt.Println(cache.Get(4)) // 输出: 4, true
}
```

这个实现包含以下特点：
- 使用了双向链表来维护节点的顺序，使得插入、删除操作都是 O(1)。
- 利用了哈希表进行快速定位，使得查找操作也是 O(1)。
- 并发安全性通过 `sync.RWMutex` 实现，对读操作使用读锁，对写操作使用写锁。
- 当缓存满时，自动淘汰最久未使用的项。

回溯算法通常用于解决组合、排列、子集等问题，在这些场景中，我们可以通过递归的方式尝试所有可能的解，并在搜索过程中剪枝以提高效率。

假设我们要生成一个给定数组的所有不重复的子集（幂集），且结果需要按字典序输出。我们可以使用回溯法来实现这一目标，并手动对临时结果进行排序或确保其自然有序以避免重复。

下面是一个示例代码，展示了如何用C++编写回溯函数而不使用内置排序函数来获取并保持子集的字典顺序：

