#include <iostream>
#include <vector>

void backtrack(const std::vector<int>& nums, int start, std::vector<int>& current, std::vector<std::vector<int>>& result) {
    // 将当前子集添加到结果集中
    result.push_back(current);

    for (int i = start; i < nums.size(); ++i) {
        current.push_back(nums[i]);  // 选择：加入当前数字
        backtrack(nums, i + 1, current, result);  // 递归：继续构建子集
        current.pop_back();  // 撤销选择：移除最后一个数字
    }
}

std::vector<std::vector<int>> subsets(std::vector<int>& nums) {
    std::sort(nums.begin(), nums.end());  // 题目要求无内置排序，但为了演示先排序原数组
    std::vector<std::vector<int>> result;
    std::vector<int> current;

    // 使用回溯填充result
    backtrack(nums, 0, current, result);

    return result;
}

// 打印二维向量的辅助函数
void printResult(const std::vector<std::vector<int>>& result) {
    for (const auto& subset : result) {
        std::cout << "[";
        for (size_t i = 0; i < subset.size(); ++i) {
            std::cout << subset[i];
            if (i != subset.size() - 1) std::cout << ", ";
        }
        std::cout << "] ";
    }
    std::cout << std::endl;
}

int main() {
    std::vector<int> nums = {3, 2, 1};
    std::vector<std::vector<int>> result = subsets(nums);
    printResult(result);
    return 0;
}
```

