在 Zig 中实现一个带有 LRU（最近最少使用）淘汰策略的缓存，可以利用双向链表和哈希表来高效地管理键值对以及它们的访问顺序。当缓存达到其容量限制时，最久未被访问的条目将从缓存中移除。

下面是一个简单的示例代码，展示了如何使用 Zig 语言编写这样一个缓存：

```zig
const std = @import("std");
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;

// 定义节点结构体用于双链表
const Node = struct {
    key: i32,
    value: i32,
    prev: ?*Node = null,
    next: ?*Node = null,
};

pub const LRUCache = struct {
    cache: HashMap(i32, *Node),
    head: ?*Node = null, // 最近使用的元素
    tail: ?*Node = null, // 最久未使用的元素
    capacity: usize,

    pub fn init(allocator: std.mem.Allocator, capacity: usize) !LRUCache {
        return LRUCache{
            .cache = HashMap(i32, *Node).init(allocator),
            .head = null,
            .tail = null,
            .capacity = capacity,
        };
    }

    pub fn deinit(self: *LRUCache) void {
        self.cache.deinit();
    }

    // 获取缓存中的值
    pub fn get(self: *LRUCache, key: i32) ?i32 {
        if (self.cache.get(key)) |node| : ({
            _ = node.value; // 访问后移动到头部
            moveToHead(node);
            return node.value;
        }) return null;
    }

    // 设置缓存中的值
    pub fn put(self: *LRUCache, key: i32, value: i32) void {
        if (self.cache.contains(key)) {
            var node = self.cache.get(key).?;
            node.value = value;
            moveToHead(node);
        } else {
            var new_node = Node{ .key = key, .value = value, .prev = null, .next = null };
            self.cache.put(key, &new_node);

            addToHead(&new_node);

            if (self.cache.count() > self.capacity) {
                var removed_tail = removeTail();
                self.cache.remove(removed_tail.key);
            }
        }
    }

private:
    // 将节点移动到头部
    fn moveToHead(node: *Node) void {
        if (node.prev) |prev| prev.next = node.next else |_| {};
        if (node.next) |next| next.prev = node.prev else |_| {};
        if (node == self.tail) self.tail = node.prev;
        addToHead(node);
    }

    // 添加新节点到头部
    fn addToHead(node: *Node) void {
        node.next = self.head;
        if (self.head) |h| h.prev = node else |_| {};
        self.head = node;
        if (self.tail == null) self.tail = node;
    }

    // 移除尾部节点
    fn removeTail() *Node {
        var old_tail = self.tail.?;
        self.tail = old_tail.prev;
        if (old_tail.prev) |prev| prev.next = null else |_| {};
        return old_tail;
    }
};

