线段树（Segment Tree）是一种用于处理区间查询和更新的二叉树数据结构，它支持在 O(log n) 时间内进行单点或区间更新以及区间查询操作。下面是一个使用 TypeScript 实现的基本线段树的例子：

```typescript
class SegmentTree {
    private tree: number[];
    private readonly n: number;

    constructor(arr: number[]) {
        this.n = arr.length;
        this.tree = new Array(4 * this.n); // 预分配足够空间
        this.build(arr, 1, 0, this.n - 1);
    }

    /**
     * 构建线段树
     */
    private build(arr: number[], node: number, start: number, end: number): void {
        if (start === end) {
            // 叶子节点只包含一个元素
            this.tree[node] = arr[start];
        } else {
            const mid = Math.floor((start + end) / 2);
            // 递归构建左右子树
            this.build(arr, 2 * node, start, mid);
            this.build(arr, 2 * node + 1, mid + 1, end);
            // 当前节点的值是其两个子节点值之和
            this.tree[node] = this.tree[2 * node] + this.tree[2 * node + 1];
        }
    }

    /**
     * 更新数组中的某个元素并维护线段树
     */
    update(index: number, val: number): void {
        this.updateUtil(1, 0, this.n - 1, index, val);
    }

    /**
     * 线段树的更新操作
     */
    private updateUtil(node: number, start: number, end: number, idx: number, val: number): void {
        if (start === end) {
            // 找到对应的叶子节点并更新
            this.tree[node] = val;
        } else {
            const mid = Math.floor((start + end) / 2);
            if (idx <= mid) {
                // 目标索引位于左半部分
                this.updateUtil(2 * node, start, mid, idx, val);
            } else {
                // 目标索引位于右半部分
                this.updateUtil(2 * node + 1, mid + 1, end, idx, val);
            }
            // 更新当前节点的值
            this.tree[node] = this.tree[2 * node] + this.tree[2 * node + 1];
        }
    }

    /**
     * 计算给定范围内的总和
     */
    query(left: number, right: number): number {
        return this.queryUtil(1, 0, this.n - 1, left, right);
    }

    /**
     * 线段树的查询操作
     */
    private queryUtil(node: number, start: number, end: number, l: number, r: number): number {
        if (r < start || end < l) {
            // 区间无交集
            return 0;
        }
        if (l <= start && end <= r) {
            // 区间完全包含于查询范围内
            return this.tree[node];
        }
        const mid = Math.floor((start + end) / 2);
        // 分别计算左右子区间的贡献然后相加
        return this.queryUtil(2 * node, start, mid, l, r)
               + this.queryUtil(2 * node + 1, mid + 1, end, l, r);
    }
}

