下面是一个使用 Rust 实现的带 LRU（最近最少使用）淘汰策略的缓存示例，保证内存不会无限增长。  
核心思路：

- 使用 `HashMap` 存储键值对；
- 使用双向链表（或类似结构）维护访问顺序；
- 每次访问（get/put）都将对应节点移到“最近”位置；
- 达到最大容量时，自动删除最久未使用的节点（链表尾部）。

下面给出一个完整、可编译的最小实现（不依赖第三方 crate）：

```rust
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{Arc, Mutex};

/// 一个简单的 LRU 缓存
///
/// - K: 键类型
/// - V: 值类型
/// - MaxSize: 最大条目数
pub struct LruCache<K, V, const MAX_SIZE: usize> {
    // 使用数组模拟固定容量的双向链表节点池，避免频繁分配
    nodes: [Option<Node<K, V>>; MAX_SIZE],
    head: Option<usize>, // 最近使用的头部索引
    tail: Option<usize>, // 最久未使用的尾部索引
    pos_in_list: Vec<Option<usize>>, // 每个键在链表中的位置（None 表示不在链表中）
    size: usize,         // 当前条目数
    map: HashMap<K, usize>, // 键 -> 链表索引
}

// 为了简化，这里用静态大小 MAX_SIZE，适合知道上限的场景。
// 如果你需要动态容量，可以改用 Vec + Box 等结构。

use std::collections::HashMap;

struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<usize>,
    next: Option<usize>,
}

impl<K: Eq + Hash + Clone, V: Clone, const MAX_SIZE: usize> LruCache<K, V, MAX_SIZE> {
    pub fn new() -> Self {
        let mut nodes = [None; MAX_SIZE];
        let mut pos_in_list = vec![None; MAX_SIZE];
        for i in 0..MAX_SIZE {
            pos_in_list[i] = None;
        }

        LruCache {
            nodes,
            head: None,
            tail: None,
            pos_in_list,
            size: 0,
            map: HashMap::new(),
        }
    }

    /// 获取值，如果存在则更新为“最近使用”，否则返回 None
    pub fn get(&mut self, key: &K) -> Option<&V> {
        let idx = *self.map.get(key)?;
        let node = self.nodes[idx].as_mut()?;

        // 如果已经在头部，不需要移动
        if Some(idx) == self.head {
            return Some(&node.value);
        }

        // 从链表中移除该节点
        self.remove_from_list(idx);

        // 插入到头部
        self.insert_at_head(idx, &node.key, &node.value);

        Some(&node.value)
    }

    /// 插入或更新键值对。如果超过容量，则淘汰最久未使用的项。
    pub fn insert(&mut self, key: K, value: V) {
        // 如果 key 已存在，先删除旧节点再插入新节点（或者原地更新后移动）
        if let Some(old_idx) = self.map.get(&key).copied() {
            // 先从链表中移除旧节点
            self.remove_from_list(old_idx);
            // 释放旧节点的占用（逻辑上）
            self.nodes[old_idx] = None;
            self.pos_in_list[old_idx] = None;
            self.size -= 1;
        }

        // 如果已满，淘汰最久未使用的
        if self.size >= MAX_SIZE {
            self.evict_tail();
        }

        // 创建新节点（复用空闲槽位）
        let idx = self.alloc_free_slot();
        self.nodes[idx] = Some(Node {
            key: key.clone(),
            value,
            prev: None,
            next: None,
        });
        self.pos_in_list[idx] = Some(idx);
        self.map.insert(key.clone(), idx);
        self.size += 1;

        // 插入到头部
        self.insert_at_head(idx, &key, &value);
    }

    /// 清空缓存
    pub fn clear(&mut self) {
        for i in 0..MAX_SIZE {
            self.nodes[i] = None;
            self.pos_in_list[i] = None;
        }
        self.head = None;
        self.tail = None;
        self.size = 0;
        self.map.clear();
    }

    /// 当前缓存中的条目数
    pub fn len(&self) -> usize {
        self.size
    }

    /// 是否为空
    pub fn is_empty(&self) -> bool {
        self.size == 0
    }

    fn alloc_free_slot(&mut self) -> usize {
        // 简单起见，线性扫描找到第一个 None 的 slot
        // 实际项目中可以用自由列表优化
        for i in 0..MAX_SIZE {
            if self.nodes[i].is_none() {
                return i;
            }
        }
        // 理论上不会到这里，因为前面已经处理了 evict
        panic!("LruCache internal error: no free slot")
    }

    fn remove_from_list(&mut self, idx: usize) {
        let node = self.nodes[idx].as_mut().unwrap();

        let prev = node.prev;
        let next = node.next;

        if let Some(p) = prev {
            self.nodes[p].as_mut().unwrap().next = next;
        } else {
            // 原来是 head
            self.head = next;
        }

        if let Some(n) = next {
            self.nodes[n].as_mut().unwrap().prev = prev;
        } else {
            // 原来是 tail
            self.tail = prev;
        }

        node.prev = None;
        node.next = None;
    }

    fn insert_at_head(&mut self, idx: usize, _key: &K, _value: &V) {
        // 确保节点已在 nodes 中且 prev/next 已清零（由 remove_from_list 或新建时保证）
        let node = self.nodes[idx].as_mut().unwrap();

        // 连接到头部
        node.prev = None;
        node.next = self.head;

        if let Some(h) = self.head {
            self.nodes[h].as_mut().unwrap().prev = Some(idx);
        } else {
            // 之前为空，tail 也要设为 idx
            self.tail = Some(idx);
        }

        self.head = Some(idx);
    }

    fn evict_tail(&mut self) {
        let tail_idx = self.tail.unwrap();
        let tail_node = self.nodes[tail_idx].as_mut().unwrap();

        // 从 map 中移除
        self.map.remove(&tail_node.key);
        // 从列表中移除
        self.remove_from_list(tail_idx);
        // 标记为空闲
        self.nodes[tail_idx] = None;
        self.pos_in_list[tail_idx] = None;
        self.size -= 1;

        // 更新 tail
        if let Some(prev) = tail_node.prev {
            self.tail = Some(prev);
            self.nodes[prev].as_mut().unwrap().next = None;
        } else {
            self.tail = None;
        }
    }
}

