## 六、示例接口清单（C++ 风格）

```cpp
template <typename T, typename L>
class SegmentTree {
public:
    using AggOp   = std::function<T(const T&, const T&)>;
    using MergeLazyFn = std::function<void(L&, const L&)>;
    using ApplyToValueFn = std::function<T(const T&, const L&)>;

    // 构建
    explicit SegmentTree(std::size_t n,
                         AggOp aggOp,
                         MergeLazyFn mergeLazy,
                         ApplyToValueFn applyToValue);

    explicit SegmentTree(const std::vector<T>& arr,
                         AggOp aggOp,
                         MergeLazyFn mergeLazy,
                         ApplyToValueFn applyToValue);

    // 更新
    void updatePoint(std::size_t pos, const T& val);

    template <typename Op>
    void updateRange(std::size_t l, std::size_t r, const Op& op);

    // 查询
    T queryRange(std::size_t l, std::size_t r) const;

    std::size_t size() const;

protected:
    // 内部实现（build, pushDown, apply, etc.）
    void build(std::size_t node, std::size_t l, std::size_t r);
    void pushDown(std::size_t node);
    void apply(std::size_t node, const L& lazyVal);

    std::vector<T> tree;
    std::vector<L> lazy;
    std::size_t n_;
    AggOp aggOp_;
    MergeLazyFn mergeLazy_;
    ApplyToValueFn applyToValue_;
};

// 线程安全包装
template <typename T, typename L>
class ThreadSafeSegmentTree : public SegmentTree<T, L> {
private:
    mutable std::mutex mtx_;

public:
    using Base = SegmentTree<T, L>;
    using Base::Base;

    void updatePoint(std::size_t pos, const T& val) override {
        std::lock_guard<std::mutex> lock(mtx_);
        Base::updatePoint(pos, val);
    }

    template <typename Op>
    void updateRange(std::size_t l, std::size_t r, const Op& op) override {
        std::lock_guard<std::mutex> lock(mtx_);
        Base::updateRange(l, r, op);
    }

    T queryRange(std::size_t l, std::size_t r) const override {
        std::lock_guard<std::mutex> lock(mtx_);
        return Base::queryRange(l, r);
    }
};
```

使用示例（求和线段树）：

```cpp
auto seg = ThreadSafeSegmentTree<long long, int64_t>(
    n,
    [](const long long& a, const long long& b) { return a + b; },
    [](int64_t& lazy, const int64_t& add) { lazy += add; }, // 简单累加
    [](const long long& val, const int64_t& add) { return val + add; }
);

seg.updatePoint(10, 100);
seg.updateRange(0, 99, [](int64_t x){ return x; }); // 这里需要根据实际 Op 设计
seg.queryRange(0, 50);
```

实际使用中，`Op` 会定义为更具体的结构，比如：

```cpp
struct RangeAdd {
    int64_t val;
};

// updateRange 内部调用时：
if (op.type == ADD) {
    apply(node, {node->lazy + op.val});
}
```

