下面用 Zig 实现一个最小堆（min-heap），并分析时间和空间复杂度。示例代码使用数组作为底层存储，支持插入、删除最小值、查看最小值等操作。

## 一、Zig 实现：最小堆

```zig
const std = @import("std");

pub fn MinHeap(comptime T: type) type {
    return struct {
        // 内部数组，1-based 索引更方便处理父子节点
        items: []T,
        count: usize,

        pub fn init(capacity: usize) !MinHeap(T) {
            const arena = std.heap.ArenaAllocator.init(std.heap.c_allocator);
            const buffer = try arena.alignedArray(T, capacity);
            return MinHeap(T){
                .items = buffer[0..],
                .count = 0,
            };
        }

        deinit(self: *MinHeap(T)) void {
            // 如果使用了 ArenaAllocator，需要释放；这里简化为只管理内存分配者自行处理
            self.items = undefined;
        }

        fn parent(i: usize) usize {
            return i / 2;
        }

        fn left_child(i: usize) usize {
            return 2 * i;
        }

        fn right_child(i: usize) usize {
            return 2 * i + 1;
        }

        // 上浮：将元素从 index 向上调整
        fn sift_up(self: *MinHeap(T), index: usize) void {
            var i = index;
            while (i > 1 and self.items[parent(i)] > self.items[i]) {
                const p = parent(i);
                std.mem.swap(T, &self.items[p], &self.items[i]);
                i = p;
            }
        }

        // 下沉：将元素从 index 向下调整
        fn sift_down(self: *MinHeap(T), index: usize) void {
            var i = index;
            const n = self.count;
            while (true) {
                const l = left_child(i);
                const r = right_child(i);
                var smallest = i;

                if (l <= n and self.items[l] < self.items[smallest]) {
                    smallest = l;
                }
                if (r <= n and self.items[r] < self.items[smallest]) {
                    smallest = r;
                }

                if (smallest == i) break;

                std.mem.swap(T, &self.items[i], &self.items[smallest]);
                i = smallest;
            }
        }

        // 插入元素
        pub fn push(self: *MinHeap(T), value: T) void {
            // 简单起见，假设容量足够；实际可动态扩容
            self.items[self.count] = value;
            self.count += 1;
            self.sift_up(self, self.count);
        }

        // 获取最小值（不删除）
        pub fn peek(self: *const MinHeap(T)) ?*T {
            if (self.count == 0) return null;
            return &self.items[1];
        }

        // 弹出最小值
        pub fn pop(self: *MinHeap(T)) ?T {
            if (self.count == 0) return null;
            const min_val = self.items[1];
            self.items[1] = self.items[self.count];
            self.count -= 1;
            if (self.count > 1) {
                self.sift_down(self, 1);
            } else if (self.count == 1) {
                // 只剩一个元素时不需要再调整
            }
            return min_val;
        }

        // 当前元素个数
        pub fn len(self: *const MinHeap(T)) usize {
            return self.count;
        }

        // 是否为空
        pub fn is_empty(self: *const MinHeap(T)) bool {
            return self.count == 0;
        }
    };
}
```

> 说明：  
> - 使用 1-based 索引，这样父节点是 `i/2`，左孩子是 `2*i`，右孩子是 `2*i+1`，逻辑更直观。  
> - `sift_up` / `sift_down` 保证堆性质：父节点 ≤ 子节点。  
> - `push` 时间复杂度 O(log n)，`pop` / `peek` 也是 O(log n) / O(1)。

如果你希望完全避免使用 Arena 等外部分配器，也可以改成由调用方传入预分配的 `[]T` 缓冲区，并在构造函数中直接初始化。

---

## 二、时间复杂度分析

设堆中元素个数为 `n`。

### 1. 插入 (`push`)

- 将新元素放到末尾：O(1)
- 然后执行 `sift_up`，最多沿着树的高度向上移动：
  - 二叉堆高度为 `⌈log₂(n+1)⌉`
  - 每次比较和交换都是 O(1)
- 总时间：**O(log n)**

### 2. 弹出最小值 (`pop`)

- 取出根节点（最小值）：O(1)
- 将最后一个元素移到根位置：O(1)
- 执行 `sift_down`，最多沿树的高度向下移动：
  - 同样最多 `⌈log₂(n+1)⌉` 层
- 总时间：**O(log n)**

### 3. 查看最小值 (`peek`)

- 直接访问 `items[1]`：
- 时间：**O(1)**

### 4. 其他操作（长度、判空）

- 都是直接访问字段或计数：
- 时间：**O(1)**

---

## 三、空间复杂度分析

- 内部使用一个连续数组 `items` 存储所有元素：
  - 若预留容量为 `C`，实际使用 `n ≤ C` 个元素。
  - 每个元素占用 `sizeof(T)` 字节。
- 额外只保存 `count` 和一个指向数组的切片：
  - 这些指针/整数占用的空间是常数级 O(1)。
- 总空间复杂度：**O(n)**，其中 n 为堆中元素个数。

如果使用固定容量且未动态扩容，则空间为 **O(C)**，但有效元素数仍为 `n ≤ C`。

---

## 四、小结

- 数据结构：基于数组的二叉堆（最小堆）。
- 操作时间复杂度：
  - `push`: O(log n)
  - `pop`: O(log n)
  - `peek`: O(1)
  - `len`, `is_empty`: O(1)
- 空间复杂度：O(n)（n 为元素个数）。

如果你需要最大堆版本、支持泛型以外的特定类型优化，或者想结合 Zig 的 `comptime` 做静态检查/编译期计算，我可以再给一个扩展版本。

