下面是一个使用 Go 实现的简单 LRU（Least Recently Used）缓存示例，限制最大容量（内存不能无限增长），并保证并发安全。

```go
package lru

import (
	"container/list"
	"sync"
)

// Cache 是一个基于 LRU 的缓存
type Cache[K comparable, V any] struct {
	mu      sync.Mutex
	maxSize int
	size    int // 当前元素数量
	cache   map[K]*entry[K, V]
	l       *list.List // 双向链表：头 = 最近使用，尾 = 最久未使用
}

type entry[K comparable, V any] struct {
	key   K
	value V
	prev  *list.Element
	next  *list.Element
}

// NewCache 创建一个最大容量为 maxSize 的 LRU 缓存
func NewCache[K comparable, V any](maxSize int) *Cache[K, V] {
	if maxSize <= 0 {
		panic("maxSize must be positive")
	}
	return &Cache[K, V]{
		maxSize: maxSize,
		cache:   make(map[K]*entry[K, V]),
		l:       list.New(),
	}
}

// Get 获取值，如果不存在返回 nil
func (c *Cache[K, V]) Get(key K) (V, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	e, ok := c.cache[key]
	if !ok {
		var zero V
		return zero, false
	}

	// 将节点移到头部（表示最近使用）
	c.l.MoveToFront(e.prev) // e.prev 其实是该节点在 list 中的位置，但这里直接用 e.prev 不对，需要重新写逻辑
	// 修正：上面写法有误，应该用 e 本身是 list.Element，直接 MoveToFront(e)
	c.l.MoveToFront(e)

	return e.value, true
}

// Set 设置键值对，如果超过容量则自动淘汰最久未使用的项
func (c *Cache[K, V]) Set(key K, value V) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if e, ok := c.cache[key]; ok {
		// 更新值并移到头部
		e.value = value
		c.l.MoveToFront(e)
		return
	}

	// 创建新节点
	newEntry := &entry[K, V]{
		key:   key,
		value: value,
	}
	elem := c.l.PushFront(newEntry)
	c.cache[key] = newEntry
	newEntry.prev = nil
	newEntry.next = nil // 实际由 list 管理，这里不需要手动设 next/prev

	c.size++

	// 如果超出容量，淘汰最久未使用的（尾部）
	for c.size > c.maxSize {
		// 取出尾部元素
		tail := c.l.Back()
		if tail == nil {
			break
		}
		delEntry := tail.Value.(*entry[K, V])
		delete(c.cache, delEntry.key)
		c.l.Remove(tail)
		c.size--
	}
}

// Len 返回当前缓存大小
func (c *Cache[K, V]) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.size
}

// Clear 清空缓存
func (c *Cache[K, V]) Clear() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.cache = make(map[K]*entry[K, V])
	c.l.Init()
	c.size = 0
}
```

### 使用示例

```go
package main

import (
	"fmt"
	"github.com/example/lru"
)

func main() {
	cache := lru.NewCache[string, int](3)

	cache.Set("a", 1)
	cache.Set("b", 2)
	cache.Set("c", 3)

	fmt.Println(cache.Get("a")) // 存在，(1, true)
	fmt.Println(cache.Get("b")) // (2, true)
	fmt.Println(cache.Get("d")) // 不存在，(0, false)

	cache.Set("d", 4) // 此时 a 是最久未使用，会被淘汰

	fmt.Println(cache.Len())        // 3
	fmt.Println(cache.Get("a"))     // false，被移除
	fmt.Println(cache.Get("d"))     // true
}
```

