### 第三步：编写第一个测试示例

假设你有一个现有的 TypeScript 工具函数文件 `src/utils/calculator.ts`：

```typescript
// src/utils/calculator.ts
export const add = (a: number, b: number): number => {
  return a + b;
};

export const divide = (a: number, b: number): number | string => {
  if (b === 0) return '除数不能为零';
  return a / b;
};
```

现在创建对应的测试文件 `src/utils/calculator.test.ts`：

```typescript
// src/utils/calculator.test.ts
import { describe, it, expect } from 'vitest'; // 如果使用 Jest，则是 import { describe, it, expect } from 'jest'
import { add, divide } from './calculator';

describe('Calculator Utility', () => {

  // 测试加法逻辑
  it('should add two positive numbers correctly', () => {
    const result = add(2, 3);
    expect(result).toBe(5);
  });

  it('should handle negative numbers', () => {
    expect(add(-1, -1)).toBe(-2);
    expect(add(-1, 1)).toBe(0);
  });

  // 测试除法及边界情况
  it('should divide two numbers correctly', () => {
    expect(divide(10, 2)).toBe(5);
  });

  it('should return an error message when dividing by zero', () => {
    const result = divide(10, 0);
    expect(result).toBe('除数不能为零');
    // 注意：这里需要断言类型，因为返回值可能是 string
    expect(typeof result).toBe('string');
  });

});
```

运行测试：
```bash
npm run test:run
```
如果看到绿色的 `✓`，说明测试通过。

