下面是一个使用 Go 实现的带 LRU（最近最少使用）淘汰策略的简单缓存示例。  
特点：

- 基于 `sync.Mutex` 保证线程安全
- 支持设置最大容量（内存上限），超过时自动淘汰最久未使用的项
- 提供 `Get` / `Set` / `Delete` 接口
- 内部使用双向链表 + 哈希表实现 O(1) 的更新和查找

```go
package main

import (
	"sync"
)

// Cache 是带 LRU 淘汰策略的缓存
type Cache[K comparable, V any] struct {
	mu       sync.Mutex
	capacity int
	size     int // 当前元素数量

	items map[K]*node[K, V]
	head  *node[K, V] // 头节点（最近使用）
	tail  *node[K, V] // 尾节点（最久未使用）
}

// node 表示双向链表的节点
type node[K comparable, V any] struct {
	key   K
	value V
	prev  *node[K, V]
	next  *node[K, V]
}

// NewCache 创建一个容量为 capacity 的 LRU 缓存
func NewCache[K comparable, V any](capacity int) *Cache[K, V] {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	c := &Cache[K, V]{
		capacity: capacity,
		items:    make(map[K]*node[K, V]),
	}
	return c
}

// Get 获取值，如果不存在返回零值和 false
func (c *Cache[K, V]) Get(key K) (V, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	n, ok := c.items[key]
	if !ok {
		var zero V
		return zero, false
	}

	// 将访问的节点移到头部（最近使用）
	c.moveToHead(n)
	return n.value, true
}

// Set 设置键值对，若超出容量则自动淘汰最久未使用的项
func (c *Cache[K, V]) Set(key K, value V) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if n, ok := c.items[key]; ok {
		// 已存在，更新值并移到头部
		n.value = value
		c.moveToHead(n)
		return
	}

	// 创建新节点
	newNode := &node[K, V]{
		key:   key,
		value: value,
	}

	// 插入到头部
	c.insertToFront(newNode)
	c.items[key] = newNode
	c.size++

	// 如果超出容量，删除尾部节点（最久未使用）
	if c.size > c.capacity {
		removed := c.removeTail()
		delete(c.items, removed.key)
		c.size--
	}
}

// Delete 删除指定键
func (c *Cache[K, V]) Delete(key K) bool {
	c.mu.Lock()
	defer c.mu.Unlock()

	n, ok := c.items[key]
	if !ok {
		return false
	}

	c.unlink(n)
	delete(c.items, key)
	c.size--
	return true
}

// Len 返回当前缓存中的元素数量
func (c *Cache[K, V]) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.size
}

// Capacity 返回缓存的最大容量
func (c *Cache[K, V]) Capacity() int {
	return c.capacity
}

// moveToHead 将节点移动到链表头部（最近使用）
func (c *Cache[K, V]) moveToHead(n *node[K, V]) {
	if n == c.head {
		return
	}
	// 从当前位置移除
	c.unlink(n)
	// 插入到头部
	c.insertToFront(n)
}

// insertToFront 将节点插入到链表头部
func (c *Cache[K, V]) insertToFront(n *node[K, V]) {
	n.next = c.head
	n.prev = nil
	if c.head != nil {
		c.head.prev = n
	}
	c.head = n
	if c.tail == nil {
		c.tail = n
	}
}

// unlink 从链表中移除节点（不调整 head/tail）
func (c *Cache[K, V]) unlink(n *node[K, V]) {
	if n.prev != nil {
		n.prev.next = n.next
	} else {
		// n 是 head
		c.head = n.next
	}

	if n.next != nil {
		n.next.prev = n.prev
	} else {
		// n 是 tail
		c.tail = n.prev
	}
	n.prev = nil
	n.next = nil
}

// removeTail 删除并返回尾部节点（最久未使用）
func (c *Cache[K, V]) removeTail() *node[K, V] {
	if c.tail == nil {
		return nil
	}
	tail := c.tail
	c.unlink(tail)
	return tail
}

// Example 使用示例
func main() {
	cache := NewCache[string, int](3)

	cache.Set("a", 1)
	cache.Set("b", 2)
	cache.Set("c", 3)

	println(cache.Get("a")) // 1, true
	println(cache.Get("b")) // 2, true

	cache.Set("d", 4) // 此时容量为 4 > 3，会淘汰最久未使用的 "c"

	println(cache.Get("c")) // "", false （已被淘汰）
	println(cache.Get("d")) // 4, true
	println(cache.Len())    // 3
}
```

