下面是一个基于 JavaScript 的简单 LRU（Least Recently Used，最近最少使用）缓存实现示例。它限制最大容量，当超过容量时自动淘汰最久未使用的项。

```js
class LRUCache {
  constructor(capacity) {
    if (capacity <= 0) {
      throw new Error('capacity must be greater than 0');
    }
    this.capacity = capacity;
    // 使用 Map 来维护 key -> node，同时利用 Map 的插入顺序特性
    this.cache = new Map();
  }

  /**
   * 获取值：如果存在则更新为“最近使用”，并返回值；否则返回 undefined
   */
  get(key) {
    if (!this.cache.has(key)) {
      return undefined;
    }

    const node = this.cache.get(key);
    // 移到尾部（最新使用）
    this.cache.delete(key);
    this.cache.set(key, node);
    return node.value;
  }

  /**
   * 设置键值对：如果超出容量，则淘汰最久未使用的项（Map 头部）
   */
  put(key, value) {
    if (this.cache.has(key)) {
      // 已存在：更新值并移到尾部
      this.cache.delete(key);
      this.cache.set(key, { key, value });
      return;
    }

    // 新插入
    this.cache.set(key, { key, value });

    // 如果超出容量，删除最久未使用的（Map 头部）
    if (this.cache.size > this.capacity) {
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
  }
}

// 使用示例
const cache = new LRUCache(2);

cache.put(1, 'a');
cache.put(2, 'b');
console.log(cache.get(1)); // 'a'，此时 1 变为最近使用
cache.put(3, 'c');         // 触发淘汰：2 被删（最久未使用）
console.log(cache.get(2)); // undefined
console.log(cache.get(3)); // 'c'

cache.put(4, 'd');         // 再次触发淘汰：1 被删
console.log(cache.get(1)); // undefined
console.log(cache.get(4)); // 'd'
```

说明要点：
- 使用 `Map` 保证：
  - O(1) 时间查找、更新、删除；
  - 插入和访问的顺序天然记录了“最近使用”关系。
- `get(key)`：找到就删除再重新插入到末尾，使其成为“最近使用”。
- `put(key, value)`：
  - 若已存在：更新值并移到末尾；
  - 若不存在：插入末尾；
  - 若大小超过 `capacity`：删除头部（最久未使用）。

