### 2. C++ 风格示例（细粒度锁 + 哈希子节点）

```cpp
template <typename CharT>
struct TrieNode {
    std::atomic<bool> isEndOfWord{false};
    std::atomic<int> wordCount{0};
    mutable std::mutex mtx;
    std::unordered_map<CharT, std::unique_ptr<TrieNode>> children;
};

template <typename KeyType>
class Trie {
public:
    using CharT = typename KeyType::char_type; // 假设 KeyType 有 char_type 别名

    explicit Trie(bool useAtomicChildren = false) : root_(new TrieNode<CharT>()) {}

    // 插入
    void insert(const KeyType& key) {
        if (key.empty()) return;
        std::vector<std::pair<TrieNode<CharT>*, std::lock_guard<std::mutex>>> lockedNodes;
        TrieNode<CharT>* cur = root_.get();

        for (size_t i = 0; i < key.size(); ++i) {
            CharT c = key[i];
            std::lock_guard<std::mutex> lock(cur->mtx);

            auto it = cur->children.find(c);
            if (it == cur->children.end()) {
                // 创建新节点
                auto newNode = std::make_unique<TrieNode<CharT>>();
                it = cur->children.emplace(c, std::move(newNode)).first;
            }
            cur = it->second.get();
            lockedNodes.emplace_back(cur, std::lock_guard<std::mutex>(cur->mtx));
        }

        // 标记结束
        cur->isEndOfWord.store(true, std::memory_order_release);
        cur->wordCount.fetch_add(1, std::memory_order_relaxed);
    }

    // 删除
    bool remove(const KeyType& key) {
        if (key.empty()) return false;
        std::vector<TrieNode<CharT>*> path;
        TrieNode<CharT>* cur = root_.get();

        for (size_t i = 0; i < key.size(); ++i) {
            CharT c = key[i];
            {
                std::lock_guard<std::mutex> lock(cur->mtx);
                auto it = cur->children.find(c);
                if (it == cur->children.end()) return false;
                cur = it->second.get();
                path.push_back(cur);
            }
        }

        // 检查是否是单词
        {
            std::lock_guard<std::mutex> lock(cur->mtx);
            if (!cur->isEndOfWord.load(std::memory_order_acquire)) {
                return false;
            }
            cur->isEndOfWord.store(false, std::memory_order_release);
            int cnt = cur->wordCount.fetch_sub(1, std::memory_order_acq_rel);
            if (cnt <= 1) {
                // 尝试回收：这里简化处理，实际需更复杂的引用计数或延迟回收
            }
        }

        // 自底向上回收空节点（可选优化）
        for (int i = static_cast<int>(path.size()) - 1; i >= 0; --i) {
            TrieNode<CharT>* node = path[i];
            if (node->children.empty() && !node->isEndOfWord.load(std::memory_order_acquire)) {
                // 在外部管理内存或使用智能指针自动回收
                // 此处仅为示意
            }
        }
        return true;
    }

    // 查找
    bool search(const KeyType& key) const {
        if (key.empty()) return false;
        const TrieNode<CharT>* cur = root_.get();
        for (size_t i = 0; i < key.size(); ++i) {
            CharT c = key[i];
            std::lock_guard<std::mutex> lock(const_cast<TrieNode<CharT>&>(*cur).mtx);
            auto it = cur->children.find(c);
            if (it == cur->children.end()) return false;
            cur = it->second.get();
        }
        return cur->isEndOfWord.load(std::memory_order_acquire);
    }

    bool startsWith(const KeyType& prefix) const {
        if (prefix.empty()) return true; // 或者根据需求定义为 false
        const TrieNode<CharT>* cur = root_.get();
        for (size_t i = 0; i < prefix.size(); ++i) {
            CharT c = prefix[i];
            std::lock_guard<std::mutex> lock(const_cast<TrieNode<CharT>&>(*cur).mtx);
            auto it = cur->children.find(c);
            if (it == cur->children.end()) return false;
            cur = it->second.get();
        }
        return true;
    }

    int countWords() const {
        // 需要遍历整棵树，这里简化为示意
        int total = 0;
        std::vector<const TrieNode<CharT>*> stack;
        stack.push_back(root_.get());
        while (!stack.empty()) {
            const TrieNode<CharT>* node = stack.back();
            stack.pop_back();
            {
                std::lock_guard<std::mutex> lock(const_cast<TrieNode<CharT>&>(*node).mtx);
                total += node->wordCount.load(std::memory_order_acquire);
                for (auto& [_, child] : node->children) {
                    stack.push_back(child.get());
                }
            }
        }
        return total;
    }

    int uniqueWords() const {
        // 类似 countWords，但只累加 isEndOfWord == true 的节点
        int total = 0;
        std::vector<const TrieNode<CharT>*> stack;
        stack.push_back(root_.get());
        while (!stack.empty()) {
            const TrieNode<CharT>* node = stack.back();
            stack.pop_back();
            {
                std::lock_guard<std::mutex> lock(const_cast<TrieNode<CharT>&>(*node).mtx);
                if (node->isEndOfWord.load(std::memory_order_acquire)) {
                    ++total;
                }
                for (auto& [_, child] : node->children) {
                    stack.push_back(child.get());
                }
            }
        }
        return total;
    }

    long memoryUsage() const {
        // 估算节点数 * 固定开销，实际可根据实现细化
        long nodes = 0;
        std::vector<const TrieNode<CharT>*> stack;
        stack.push_back(root_.get());
        while (!stack.empty()) {
            const TrieNode<CharT>* node = stack.back();
            stack.pop_back();
            {
                std::lock_guard<std::mutex> lock(const_cast<TrieNode<CharT>&>(*node).mtx);
                ++nodes;
                for (auto& [_, child] : node->children) {
                    stack.push_back(child.get());
                }
            }
        }
        return nodes * sizeof(TrieNode<CharT>);
    }

    void clear() {
        // 递归释放整棵树，注意线程安全：最好先 stop 所有写入操作
        std::lock_guard<std::mutex> rootLock(root_->mtx);
        root_->children.clear();
        root_->isEndOfWord.store(false, std::memory_order_release);
        root_->wordCount.store(0, std::memory_order_release);
    }

private:
    std::unique_ptr<TrieNode<CharT>> root_;
};
```

> 注：上述代码为概念性示例，未做完整异常处理、内存池、无锁优化等生产级细节。

