下面是一个使用 TypeScript 实现的带 LRU（Least Recently Used，最近最少使用）淘汰策略的缓存示例。它支持：

- 设置最大容量（内存上限）
- 自动按 LRU 规则淘汰最久未使用的项
- `get(key)` / `set(key, value)` / `has(key)` / `delete(key)` 等常用操作

```ts
// LRUCache.ts

type CacheValue = any;

interface Node<K, V> {
  key: K;
  value: V;
  prev: Node<K, V> | null;
  next: Node<K, V> | null;
}

class DoublyLinkedList<K, V> {
  private head: Node<K, V> | null = null;
  private tail: Node<K, V> | null = null;
  private size: number = 0;

  // 将节点移到头部（表示最近使用）
  moveToHead(node: Node<K, V>): void {
    if (!this.head || !this.tail) return;

    const { prev, next } = node;

    // 如果已经在头部，无需移动
    if (prev === this.head && next === this.tail) return;

    // 从原位置断开
    if (prev) {
      prev.next = next;
    } else {
      this.head = next;
    }

    if (next) {
      next.prev = prev;
    } else {
      this.tail = prev;
    }

    // 插入到头部
    node.prev = null;
    node.next = this.head;
    if (this.head) {
      this.head.prev = node;
    }
    this.head = node;
    if (!this.tail) {
      this.tail = node;
    }
  }

  // 在头部添加新节点
  addAtHead(node: Node<K, V>): void {
    node.prev = null;
    node.next = this.head;
    if (this.head) {
      this.head.prev = node;
    }
    this.head = node;
    if (!this.tail) {
      this.tail = node;
    }
    this.size++;
  }

  // 删除指定节点
  removeNode(node: Node<K, V>): void {
    if (!node) return;

    const { prev, next } = node;

    if (prev) {
      prev.next = next;
    } else {
      this.head = next;
    }

    if (next) {
      next.prev = prev;
    } else {
      this.tail = prev;
    }

    node.prev = null;
    node.next = null;
    this.size--;
  }

  // 删除尾部节点并返回
  removeTail(): Node<K, V> | undefined {
    if (!this.tail) return undefined;
    const node = this.tail;
    this.removeNode(node);
    return node;
  }

  getSize(): number {
    return this.size;
  }
}

export class LRUCache<K, V> {
  private capacity: number;
  private map: Map<K, Node<K, V>>;
  private list: DoublyLinkedList<K, V>;

  constructor(capacity: number) {
    if (capacity <= 0) {
      throw new Error("Capacity must be greater than 0");
    }
    this.capacity = capacity;
    this.map = new Map();
    this.list = new DoublyLinkedList();
  }

  get(key: K): V | undefined {
    const node = this.map.get(key);
    if (!node) {
      return undefined;
    }
    // 更新为最近使用
    this.list.moveToHead(node);
    return node.value;
  }

  set(key: K, value: V): void {
    const existingNode = this.map.get(key);

    if (existingNode) {
      // 更新值并标记为最近使用
      existingNode.value = value;
      this.list.moveToHead(existingNode);
    } else {
      const newNode: Node<K, V> = { key, value, prev: null, next: null };
      this.list.addAtHead(newNode);
      this.map.set(key, newNode);

      // 超过容量则淘汰最久未使用的（尾部）
      while (this.list.getSize() > this.capacity) {
        const tailNode = this.list.removeTail();
        if (tailNode) {
          this.map.delete(tailNode.key);
        }
      }
    }
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  delete(key: K): boolean {
    const node = this.map.get(key);
    if (!node) {
      return false;
    }
    this.list.removeNode(node);
    this.map.delete(key);
    return true;
  }

  clear(): void {
    this.map.clear();
    this.list.head = null;
    this.list.tail = null;
    this.list.size = 0;
  }

  size(): number {
    return this.map.size;
  }

  keys(): K[] {
    return Array.from(this.map.keys());
  }

  values(): V[] {
    return Array.from(this.map.values()).map(n => n.value);
  }
}
```

