def dfs_iterative(graph, start):
    n = len(graph)
    visited = [False] * n
    order = []
    stack = [start]
    visited[start] = True

    while stack:
        node = stack.pop()
        order.append(node)

        # 为了保持与递归类似的“先访问第一个邻居”的顺序，
        # 可以倒序压栈（这样出栈时先处理第一个邻居）
        for neighbor in reversed(graph[node]):
            if not visited[neighbor]:
                visited[neighbor] = True
                stack.append(neighbor)

    return order
```

