下面是一个使用 TypeScript 实现的带 LRU（Least Recently Used）淘汰策略的缓存示例。  
特点：

- 固定最大容量 `maxSize`，超过则自动淘汰最久未使用的项。
- 访问或设置时更新“最近使用”顺序。
- 支持类型泛型 `<K, V>`。
- 内部使用 `Map` + 双向链表思想（通过 `Map` 记录节点在链表中的位置）。

```ts
class LRUCache<K, V> {
  private maxSize: number;
  // key -> node
  private map = new Map<K, Node<K, V>>();
  // 头结点（最近使用）和尾结点（最久未使用）
  private head: Node<K, V> | null = null;
  private tail: Node<K, V> | null = null;

  constructor(maxSize: number) {
    if (maxSize <= 0) {
      throw new Error("maxSize must be greater than 0");
    }
    this.maxSize = maxSize;
  }

  get(key: K): V | undefined {
    const node = this.map.get(key);
    if (!node) {
      return undefined;
    }
    this.moveToHead(node);
    return node.value;
  }

  set(key: K, value: V): void {
    let node = this.map.get(key);

    if (node) {
      // 更新值并移到头部
      node.value = value;
      this.moveToHead(node);
    } else {
      // 新建节点
      node = new Node(key, value);
      this.map.set(key, node);

      // 插入到头部
      this.addToHead(node);

      // 如果超过容量，淘汰尾部
      if (this.map.size > this.maxSize) {
        this.evictTail();
      }
    }
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  delete(key: K): boolean {
    const node = this.map.get(key);
    if (!node) return false;

    this.removeNode(node);
    this.map.delete(key);
    return true;
  }

  clear(): void {
    this.map.clear();
    this.head = null;
    this.tail = null;
  }

  size(): number {
    return this.map.size;
  }

  private addToHead(node: Node<K, V>): void {
    if (!this.head) {
      this.head = node;
      this.tail = node;
      return;
    }

    // 当前头结点的 next 指向新节点
    node.prev = this.head;
    node.next = this.head.next;

    if (this.head.next) {
      this.head.next!.prev = node;
    } else {
      // 原来是只有一个节点
      this.tail = node;
    }

    this.head = node;
  }

  private moveToHead(node: Node<K, V>): void {
    if (node === this.head) return;

    // 从链表中移除
    this.removeNode(node);

    // 再插入到头部
    this.addToHead(node);
  }

  private removeNode(node: Node<K, V>): void {
    if (node.prev) {
      node.prev.next = node.next;
    } else {
      // node 是头结点
      this.head = node.next;
    }

    if (node.next) {
      node.next!.prev = node.prev;
    } else {
      // node 是尾结点
      this.tail = node.prev;
    }

    // 断开与原节点的连接
    node.prev = null;
    node.next = null;
  }

  private evictTail(): void {
    if (!this.tail) return;

    const key = this.tail.key;
    this.map.delete(key);

    // 移动到前一个节点作为新的 tail
    if (this.tail.prev) {
      this.tail = this.tail.prev;
      this.tail.next = null;
    } else {
      // 只剩下一个节点被删了
      this.head = null;
      this.tail = null;
    }
  }
}

class Node<K, V> {
  constructor(
    public key: K,
    public value: V
  ) {}

  prev: Node<K, V> | null = null;
  next: Node<K, V> | null = null;
}

// 使用示例
const cache = new LRUCache<string, number>(3);

cache.set("a", 1);
cache.set("b", 2);
cache.set("c", 3);

console.log(cache.get("a")); // 1 -> "a" 变成最近使用
console.log(cache.get("b")); // 2

cache.set("d", 4); // 现在大小变为 4，需要淘汰最久未使用的 "c"

console.log(cache.has("c")); // false
console.log(cache.get("c")); // undefined
console.log(cache.get("d")); // 4

console.log(cache.size()); // 3
```

如果你需要支持异步操作、持久化、或者更复杂的配置（如自定义 TTL、统计命中率等），可以在此基础上扩展。

下面是一个用 Zig 实现的带 LRU（最近最少使用）淘汰策略的简单缓存示例。它保证：

- 最大容量有限（不能无限增长）
- 访问/插入时更新“最近使用”顺序
- 超过容量时自动淘汰最久未使用的项

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;

/// 缓存节点，记录 key、value 和最近使用时间戳
pub fn CacheNode(comptime K: type, comptime V: type) type {
    return struct {
        key: K,
        value: V,
        prev: ?*CacheNode(K, V) = null,
        next: ?*CacheNode(K, V) = null,
    };
}

/// LRU 双向链表 + 哈希表实现
pub fn LRUCache(comptime K: type, comptime V: type, comptime Capacity: usize) type {
    const Node = CacheNode(K, V);

    return struct {
        const Self = @This();

        // 双向链表头尾哨兵
        head: Node, // 伪头节点（实际不存数据）
        tail: Node, // 伪尾节点（实际不存数据）

        // 哈希表：key -> *Node
        map: std.AutoHashMap(K, *Node),

        capacity: usize,
        size: usize,

        pub fn init(allocator: Allocator) !Self {
            var self = Self{
                .head = .{},
                .tail = .{},
                .map = try std.AutoHashMap(K, *Node).init(allocator),
                .capacity = Capacity,
                .size = 0,
            };

            // 初始化哨兵节点的双向链接
            self.head.prev = &self.tail;
            self.head.next = &self.tail;
            self.tail.prev = &self.head;
            self.tail.next = &self.head;

            return self;
        }

        deinit(self: *Self) void {
            self.map.deinit();
        }

        /// 获取值，若存在则更新为“最近使用”，否则返回 null
        pub fn get(self: *Self, key: K) ?V {
            const node_ptr = self.map.get(key) orelse return null;
            const node = node_ptr.*;

            // 从链表中移除当前节点
            self.unlink(node);

            // 移动到头部（最近使用）
            self.moveToHead(node);

            return node.value;
        }

        /// 插入或更新键值对；若超出容量则淘汰最久未使用的项
        pub fn put(self: *Self, key: K, value: V) void {
            if (self.map.contains(key)) {
                // 已存在：更新值并移到头部
                const node_ptr = self.map.get(key).?;
                node_ptr.value = value;
                self.unlink(node_ptr.*);
                self.moveToHead(node_ptr.*);
                return;
            }

            // 新插入
            var node = Node{
                .key = key,
                .value = value,
                .prev = null,
                .next = null,
            };

            // 插入到头部
            self.linkBefore(&self.head, &node);
            self.map.put(key, &node) catch |e| {
                // 内存不足时直接删除刚插入的节点
                _ = self.unlinkNode(&node);
                std.debug.assert(e == error.OutOfMemory);
                return;
            };

            self.size += 1;

            // 如果超出容量，淘汰最久未使用的（即尾部前面的那个）
            if (self.size > self.capacity) {
                self.evictTail();
            }
        }

        fn unlink(self: *Self, node: *Node) void {
            node.prev.?.next = node.next;
            node.next.?.prev = node.prev;
        }

        fn linkBefore(self: *Self, before: *Node, node: *Node) void {
            node.prev = before.prev;
            node.next = before;
            node.prev.?.next = node;
            before.prev = node;
        }

        fn moveToHead(self: *Self, node: *Node) void {
            self.unlink(node);
            self.linkBefore(&self.head, node);
        }

        fn evictTail(self: *Self) void {
            // 最久未使用的是 tail.prev
            const victim = self.tail.prev.?;
            if (victim == &self.head) return; // 不应该发生

            // 从链表中移除
            self.unlink(victim);

            // 从哈希表中删除
            _ = self.map.remove(victim.key);

            self.size -= 1;
        }

        fn unlinkNode(self: *Self, node: *Node) void {
            _ = self.map.remove(node.key);
            self.unlink(node);
            self.size -= 1;
        }
    };
}

test "LRU cache basic" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var cache = try LRUCache(u32, u32, 2).init(alloc);
    defer cache.deinit();

    cache.put(1, 10);
    cache.put(2, 20);

    try std.testing.expectEqual(@as(?u32, 10), cache.get(1));          // 命中，1 变为最近使用
    try std.testing.expectEqual(@as(?u32, 20), cache.get(2));          // 命中，2 变为最近使用

    cache.put(3, 30); // 容量为 2，应淘汰 1

    try std.testing.expectEqual(@as(?u32, null), cache.get(1));       // 1 被淘汰
    try std.testing.expectEqual(@as(?u32, 20), cache.get(2));          // 2 仍在
    try std.testing.expectEqual(@as(?u32, 30), cache.get(3));          // 3 插入

    cache.put(4, 40); // 淘汰 2

    try std.testing.expectEqual(@as(?u32, null), cache.get(2));       // 2 被淘汰
    try std.testing.expectEqual(@as(?u32, 30), cache.get(3));
    try std.testing.expectEqual(@as(?u32, 40), cache.get(4));
}
```

说明要点：

- `LRUCache` 是一个泛型结构：`LRUCache(KeyType, ValueType, MaxCapacity)`。
- 使用双向链表维护访问顺序：
  - 头部附近是“最近使用”的，尾部附近是“最久未使用”的。
  - 每次 `get` / `put` 命中或新插入都将其移到头部。
- 使用 `std.AutoHashMap` 做 O(1) 查找。
- `capacity` 固定，当元素数量超过 `capacity` 时调用 `evictTail()` 淘汰最久未使用的项。
- 通过 Arena 分配器管理生命周期，避免手动释放节点的麻烦。

如果你需要支持自定义比较器、可配置分配器、或者想改成线程安全版本，可以在此基础上继续扩展。

下面给出一个面向生产场景的跳表（Skip List）API 设计思路，兼顾：

- 线程安全（并发读写）
- 内存效率（减少冗余指针、可配置层级、回收机制）
- 易用性与可扩展性

示例以 Java 风格伪代码展示，但思想适用于 C++/Go/Rust 等语言。

---

## 一、核心设计目标

1. **线程安全**
   - 支持高并发读（Read-Copy-Update / 无锁读）
   - 写操作使用细粒度锁或无锁结构（如 CAS + 局部自旋），避免整表锁。
2. **内存效率**
   - 每个节点只存必要的前驱后继指针（上层 + 下层）。
   - 支持“层数随机化”与“最大层数限制”，避免过度分配。
   - 提供懒释放 / 批量回收机制，减少频繁 GC 压力。
3. **性能**
   - 查找、插入、删除平均 O(log n)。
   - 写放大可控，避免大量临时节点导致内存抖动。

---

## 二、接口定义（Java 风格）

```java
public interface SkipList<K, V> {
    // ==================== 基本操作 ====================

    /**
     * 插入或更新键值对。
     * 若 key 已存在，则用新 value 覆盖旧 value。
     */
    boolean put(K key, V value);

    /**
     * 根据 key 获取 value。
     * 不存在则返回 null（或可选抛出异常/返回 Optional）。
     */
    V get(K key);

    /**
     * 删除指定 key。
     * 若存在则返回 true，否则 false。
     */
    boolean remove(K key);

    /**
     * 判断是否包含某 key。
     */
    boolean contains(K key);

    /**
     * 清空所有元素。
     * 注意：在多线程环境下调用时，应保证当前其他操作不会依赖被清空的中间状态。
     */
    void clear();

    /**
     * 获取当前元素个数（近似或精确，视实现而定）。
     */
    long size();

    /**
     * 判断是否为空。
     */
    boolean isEmpty();

    // ==================== 范围查询 ====================

    /**
     * 返回所有 >= key 且 <= endKey 的键值对列表。
     * 结果按 key 升序排列。
     * 注意：遍历过程中若发生删改，可能看到不一致视图（强一致需额外同步）。
     */
    List<Map.Entry<K, V>> range(K fromKey, K toKey);

    /**
     * 返回所有 > fromKey 且 <= toKey 的键值对。
     */
    List<Map.Entry<K, V>> rightOpenRange(K fromKey, K toKey);

    /**
     * 返回所有 < toKey 的键值对。
     */
    List<Map.Entry<K, V>> lessThan(K toKey);

    // ==================== 迭代器（线程安全视图） ====================

    /**
     * 返回一个基于当前快照的有序迭代器。
     * 迭代器内部持有对跳表的弱引用或快照，遍历时不阻塞写操作，
     * 但可能看到“旧数据”或“部分新数据”。
     */
    Iterator<Map.Entry<K, V>> iterator();

    /**
     * 返回从某个 key（含）开始的有序子迭代器。
     */
    Iterator<Map.Entry<K, V>> iteratorFrom(K fromKey);

    /**
     * 返回到某个 key（不含）结束的有序子迭代器。
     */
    Iterator<Map.Entry<K, V>> iteratorTo(K toKey);

    // ==================== 统计与调试 ====================

    /**
     * 返回当前最大层数（用于调优和监控）。
     */
    int maxLevel();

    /**
     * 返回当前实际使用的节点总数（可用于监控内存）。
     */
    long nodeCount();

    /**
     * 重置随机层生成种子（用于测试或重现行为）。
     */
    void resetRandomSeed(long seed);
}
```

