## 二、核心接口设计

### 1. 主类模板

```cpp
template <typename T, typename AggFunc>
class SegmentTree {
public:
    // 聚合函数需满足结合律，例如：
    // AggFunc op(const T& a, const T& b) -> T
    using value_type = T;
    using aggregate_func = AggFunc;

    // 构造函数：从初始数组构建
    explicit SegmentTree(const std::vector<T>& data);

    // 构造空树（长度固定），后续通过 update 填充
    explicit SegmentTree(std::size_t n);

    // 拷贝/移动语义（视需求决定是否深拷贝）
    SegmentTree(const SegmentTree&) = delete;          // 默认不推荐浅拷贝，避免共享状态
    SegmentTree& operator=(const SegmentTree&) = delete;
    SegmentTree(SegmentTree&&) noexcept = default;
    SegmentTree& operator=(SegmentTree&&) noexcept = default;

    // =====================
    // 查询接口（线程安全读）
    // =====================

    // 单点查询：返回位置 pos 的值
    T query_point(std::size_t pos) const;

    // 区间查询：返回 [l, r] 的聚合结果（闭区间）
    T query_range(std::size_t l, std::size_t r) const;

    // =====================
    // 更新接口（线程安全写）
    // =====================

    // 单点更新：将位置 pos 的值设为 val
    void update_point(std::size_t pos, T val);

    // 区间更新：对 [l, r] 应用聚合操作（例如加一个值）
    // 具体行为由 AggFunc 定义；这里提供一个通用“区间加”示例
    void range_add(std::size_t l, std::size_t r, T delta);

    // 批量更新：直接设置整个区间的值（覆盖式）
    void range_set(std::size_t l, std::size_t r, T val);

    // =====================
    // 元信息
    // =====================

    std::size_t size() const;
    bool empty() const;

private:
    // 内部实现细节略
};
```

