## 三、C++ 实现示例（简要）

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <stack>
#include <unordered_set>

using namespace std;

// BFS
vector<int> bfs(const vector<vector<int>>& graph, int start) {
    unordered_set<int> visited;
    queue<int> q;
    vector<int> order;

    visited.insert(start);
    q.push(start);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);

        for (int v : graph[u]) {
            if (visited.find(v) == visited.end()) {
                visited.insert(v);
                q.push(v);
            }
        }
    }
    return order;
}

// 递归 DFS
void dfsRecursiveHelper(const vector<vector<int>>& graph, int u,
                        unordered_set<int>& visited, vector<int>& order) {
    visited.insert(u);
    order.push_back(u);
    for (int v : graph[u]) {
        if (visited.find(v) == visited.end()) {
            dfsRecursiveHelper(graph, v, visited, order);
        }
    }
}

vector<int> dfsRecursive(const vector<vector<int>>& graph, int start) {
    unordered_set<int> visited;
    vector<int> order;
    dfsRecursiveHelper(graph, start, visited, order);
    return order;
}

// 非递归 DFS
vector<int> dfsIterative(const vector<vector<int>>& graph, int start) {
    unordered_set<int> visited;
    stack<int> st;
    vector<int> order;

    visited.insert(start);
    st.push(start);

    while (!st.empty()) {
        int u = st.top();
        st.pop();
        order.push_back(u);

        // 倒序遍历，使顺序更接近递归
        for (auto it = graph[u].rbegin(); it != graph[u].rend(); ++it) {
            int v = *it;
            if (visited.find(v) == visited.end()) {
                visited.insert(v);
                st.push(v);
            }
        }
    }
    return order;
}

int main() {
    // 构造图 (0..5)
    vector<vector<int>> graph(6);
    graph[0] = {1, 2};
    graph[1] = {0, 3, 4};
    graph[2] = {0, 5};
    graph[3] = {1};
    graph[4] = {1, 5};
    graph[5] = {2, 4};

    cout << "BFS: ";
    for (int x : bfs(graph, 0)) cout << x << " ";
    cout << "\n";

    cout << "DFS recursive: ";
    for (int x : dfsRecursive(graph, 0)) cout << x << " ";
    cout << "\n";

    cout << "DFS iterative: ";
    for (int x : dfsIterative(graph, 0)) cout << x << " ";
    cout << "\n";

    return 0;
}
```

