下面是一个用 Zig 实现的简单 LRU 缓存示例，支持：

- 固定最大容量（内存不会无限增长）
- 按访问频率淘汰最久未使用的项
- 基本操作：`put(key, value)`、`get(key)`、`remove(key)`

代码使用标准库 + 自定义链表实现 LRU，不依赖第三方包。

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;

/// LRU Cache 节点
pub const Node = struct {
    key: []const u8,
    value: []const u8,
    prev: ?*Node = null,
    next: ?*Node = null,
};

/// LRU Cache
pub fn LRUCache(comptime Capacity: usize) type {
    return struct {
        const Self = @This();

        allocator: Allocator,
        capacity: usize,
        size: usize = 0,

        // 头尾哨兵节点，方便处理边界
        head: *Node = undefined,
        tail: *Node = undefined,

        // key -> node 映射
        map: std.StringHashMap(*Node),

        fn init(allocator: Allocator) !Self {
            // 哨兵节点本身也需要分配内存
            const sentinel = try allocator.create(Node);
            sentinel.* = .{
                .key = "",
                .value = "",
                .prev = null,
                .next = null,
            };

            return Self{
                .allocator = allocator,
                .capacity = Capacity,
                .size = 0,
                .head = sentinel,
                .tail = sentinel,
                .map = std.StringHashMap(*Node).init(allocator),
            };
        }

        deinit(self: *Self) void {
            var it = self.map.iterator();
            while (it.next()) |entry| {
                const node_ptr = entry.value_ptr;
                // 释放 key/value
                if (node_ptr.key.len > 0) {
                    self.allocator.free(node_ptr.key);
                }
                if (node_ptr.value.len > 0) {
                    self.allocator.free(node_ptr.value);
                }
                self.allocator.destroy(node_ptr);
            }
            self.map.deinit();

            // 销毁哨兵
            self.allocator.destroy(self.head);
        }

        /// 获取值，若不存在返回 null
        fn get(self: *Self, key: []const u8) ?[]const u8 {
            const node_opt = self.map.getByKeyOwned(key) orelse return null;
            const node = node_opt.value_ptr;

            // 如果已经在头部附近（即最近使用），不需要移动
            // 否则移动到头部
            if (node != self.head.next) {
                // 从当前位置移除
                if (node.prev) |prev_node| {
                    prev_node.next = node.next;
                } else {
                    // node == head (理论上不应发生，因为 head 是哨兵)
                }

                if (node.next) |next_node| {
                    next_node.prev = node.prev;
                } else {
                    // node == tail
                    self.tail = node.prev;
                }

                // 插入到 head 后面
                node.prev = self.head;
                node.next = self.head.next;

                if (self.head.next) |first| {
                    first.prev = node;
                } else {
                    // 空列表（不应该）
                    self.tail = node;
                }
                self.head.next = node;
            }

            return node.value;
        }

        /// 插入或更新键值对
        fn put(self: *Self, key: []const u8, value: []const u8) void {
            // 先尝试查找是否已存在
            if (self.map.get(key)) |existing_node| {
                // 更新 value
                if (existing_node.value.len > 0) {
                    self.allocator.free(existing_node.value);
                }
                existing_node.value = self.allocator.dupeZ(u8, value) catch |err| {
                    std.debug.print("Failed to allocate value: {}\n", .{err});
                    return;
                };

                // 移动到头部
                _ = self.moveToFront(existing_node);
                return;
            }

            // 新节点
            const node = self.allocator.create(Node) catch |err| {
                std.debug.print("Failed to allocate node: {}\n", .{err});
                return;
            };
            node.* = .{
                .key = self.allocator.dupeZ(u8, key) catch |err| {
                    std.debug.print("Failed to allocate key: {}\n", .{err});
                    self.allocator.destroy(node);
                    return;
                },
                .value = self.allocator.dupeZ(u8, value) catch |err| {
                    std.debug.print("Failed to allocate value: {}\n", .{err});
                    self.allocator.free(node.key);
                    self.allocator.destroy(node);
                    return;
                },
                .prev = null,
                .next = null,
            };

            // 检查容量
            if (self.size >= self.capacity) {
                // 需要淘汰最久未使用的（tail 前面的那个）
                const evict_node = self.evictTail();
                if (evict_node != null) {
                    const evicted = evict_node.?;
                    // 从 map 中删除
                    _ = self.map.remove(evicted.key);
                    // 释放 evicted 的 key/value
                    if (evicted.key.len > 0) {
                        self.allocator.free(evicted.key);
                    }
                    if (evicted.value.len > 0) {
                        self.allocator.free(evicted.value);
                    }
                    self.allocator.destroy(evicted);
                }
            }

            // 插入到头部
            _ = self.insertAtHead(node);
            _ = self.map.put(std.string.ascii.allocLowerString(self.allocator, key) catch |err| {
                std.debug.print("Failed to alloc lower key: {}\n", .{err});
                return error.OutOfMemory;
            }, node);

            self.size += 1;
        }

        fn remove(self: *Self, key: []const u8) bool {
            if (!self.map.contains(key)) return false;

            const node_opt = self.map.get(key) orelse return false;
            const node = node_opt.value_ptr;

            // 从链表中移除
            if (node.prev) |prev_node| {
                prev_node.next = node.next;
            } else {
                // node == head (不可能，因为 head 是哨兵)
            }

            if (node.next) |next_node| {
                next_node.prev = node.prev;
            } else {
                self.tail = node.prev;
            }

            // 清理
            if (node.key.len > 0) {
                self.allocator.free(node.key);
            }
            if (node.value.len > 0) {
                self.allocator.free(node.value);
            }
            self.allocator.destroy(node);

            _ = self.map.remove(key);
            self.size -= 1;
            return true;
        }

        fn moveToFront(self: *Self, node: *Node) bool {
            if (node == self.head.next) return true; // 已在头部

            // 从当前位置移除
            if (node.prev) |prev_node| {
                prev_node.next = node.next;
            } else {
                // 理论上不会到这里
                return false;
            }

            if (node.next) |next_node| {
                next_node.prev = node.prev;
            } else {
                self.tail = node.prev;
            }

            // 插入到 head 后面
            node.prev = self.head;
            node.next = self.head.next;

            if (self.head.next) |first| {
                first.prev = node;
            } else {
                self.tail = node;
            }
            self.head.next = node;

            return true;
        }

        fn insertAtHead(self: *Self, node: *Node) bool {
            if (node.prev != null or node.next != null) return false; // 不应重复插入

            node.prev = self.head;
            node.next = self.head.next;

            if (self.head.next) |first| {
                first.prev = node;
            } else {
                self.tail = node;
            }
            self.head.next = node;

            return true;
        }

        fn evictTail(self: *Self) ?*Node {
            if (self.tail == self.head) return null; // 没有可淘汰的

            const evict_node = self.tail.prev orelse return null;
            // 从链表中移除
            if (evict_node.prev) |prev_node| {
                prev_node.next = evict_node.next;
            } else {
                // evict_node == head (不应该)
            }

            if (evict_node.next) |next_node| {
                next_node.prev = evict_node.prev;
            } else {
                self.tail = evict_node.prev;
            }

            return evict_node;
        }
    };
}

