    try std.testing.expect(cache.get("a") == null);
    try std.testing.expectEqualStrings(cache.get("b").?, "2");
    try std.testing.expectEqualStrings(cache.get("c").?, "3");
    try std.testing.expectEqualStrings(cache.get("d").?, "4");

    // 访问 b，使 b 变为最近使用
    _ = cache.get("b");

    // 再 put e，应该淘汰 c
    cache.put("e", "5");

    try std.testing.expect(cache.get("a") == null);
    try std.testing.expectEqualStrings(cache.get("b").?, "2");
    try std.testing.expect(cache.get("c") == null);
    try std.testing.expectEqualStrings(cache.get("d").?, "4");
    try std.testing.expectEqualStrings(cache.get("e").?, "5");
}
