    bool remove(const K& key);                   // 成功删除返回 true
    std::pair<V*, bool> extract(const K& key);   // 取出并删除，返回旧值指针

    // 尺寸与清空
    std::size_t size() const;
    void clear();

    // 迭代器（只读 / 可写）
    struct Iterator;
    using const_iterator = Iterator;
    using iterator = Iterator;

    iterator begin();
    iterator end();
    const_iterator begin() const;
    const_iterator end() const;

