下面是一个基于 JavaScript 的 LRU（最近最少使用）缓存实现示例，支持：

- 设置键值对 `set(key, value)`
- 获取值 `get(key)`
- 自动淘汰最久未使用的项，防止内存无限增长
- 可自定义最大容量 `maxSize`

```js
class LRUCache {
  constructor(maxSize) {
    if (maxSize <= 0) {
      throw new Error('maxSize must be greater than 0');
    }
    this.maxSize = maxSize;
    this.cache = new Map(); // key -> { value, lastAccessTime }
    this.time = 0; // 简单的时间戳计数器
  }

  // 获取值，并更新访问顺序
  get(key) {
    if (!this.cache.has(key)) {
      return undefined;
    }

    const entry = this.cache.get(key);
    entry.lastAccessTime = ++this.time; // 更新为最新访问时间

    // 将当前访问的项移到“最近”的位置（Map 本身按插入顺序，我们这里通过重新 set 实现）
    this.cache.delete(key);
    this.cache.set(key, entry);

    return entry.value;
  }

  // 设置键值对，若超过容量则淘汰最久未使用的项
  set(key, value) {
    if (!this.cache.has(key)) {
      // 如果新插入后超过容量，先清理最久未使用的
      if (this.cache.size >= this.maxSize) {
        // Map 中第一个元素是最久未使用的（因为我们每次 set/get 都保持顺序）
        const firstKey = this.cache.keys().next().value;
        this.cache.delete(firstKey);
      }

      this.cache.set(key, {
        value,
        lastAccessTime: ++this.time
      });
    } else {
      // 已存在，更新值并更新访问时间
      const entry = this.cache.get(key);
      entry.value = value;
      entry.lastAccessTime = ++this.time;
      // 同样通过 delete+set 保证它在末尾（最近使用）
      this.cache.delete(key);
      this.cache.set(key, entry);
    }
  }

  // 可选：获取当前缓存大小
  size() {
    return this.cache.size;
  }

  // 可选：清空缓存
  clear() {
    this.cache.clear();
  }
}

// 使用示例
const cache = new LRUCache(3);

cache.set('a', 1);
cache.set('b', 2);
cache.set('c', 3);

console.log(cache.get('a')); // 1，此时 a 变为最新
console.log(cache.get('b')); // 2，b 变为最新
// 现在顺序是：c, a, b（b 最新，c 最旧）

cache.set('d', 4); // 触发淘汰，c 被移除
console.log(cache.get('c')); // undefined，已被淘汰
console.log(cache.size());   // 3

console.log(cache.get('a')); // 1，a 变为最新
console.log(cache.get('b')); // 2，b 变为最新
// 再次 set(e,5)，会淘汰 a（因为现在是 c? 不，c 已经不在，实际顺序是 b,d,a...）
cache.set('e', 5);
console.log(cache.get('a')); // undefined，a 被淘汰
```

要点说明：

- 使用 `Map` 来存储键值对，并利用其“访问/插入顺序”特性。
- 每次 `get` 或 `set` 时，都将对应项移到“最近使用”位置（通过 `delete + set`）。
- 当容量达到 `maxSize` 时，删除 `Map` 中的第一个元素（即最久未使用的项）。
- 时间戳 `lastAccessTime` 可用于扩展更复杂的策略（如带优先级、过期时间等），当前示例用简单递增计数器即可满足基本 LRU 行为。

