```go
package main

import (
	"container/heap"
	"fmt"
)

// UnionFind 结构体实现并查集
type UnionFind struct {
	parent []int
	rank   []int
}

// NewUnionFind 初始化并查集
func NewUnionFind(n int) *UnionFind {
	uf := &UnionFind{
		parent: make([]int, n),
		rank:   make([]int, n),
	}
	for i := 0; i < n; i++ {
		uf.parent[i] = i
		uf.rank[i] = 0
	}
	return uf
}

// Find 查找根节点，带路径压缩
func (uf *UnionFind) Find(x int) int {
	if uf.parent[x] != x {
		uf.parent[x] = uf.Find(uf.parent[x])
	}
	return uf.parent[x]
}

// Union 合并两个集合，按秩合并
func (uf *UnionFind) Union(x, y int) {
	rootX := uf.Find(x)
	rootY := uf.Find(y)
	if rootX == rootY {
		return
	}
	if uf.rank[rootX] < uf.rank[rootY] {
		uf.parent[rootX] = rootY
	} else if uf.rank[rootX] > uf.rank[rootY] {
		uf.parent[rootY] = rootX
	} else {
		uf.parent[rootY] = rootX
		uf.rank[rootX]++
	}
}

// IntHeap 实现最小堆接口，用于合并有序数组
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x interface{}) {
	*h = append(*h, x.(int))
}
func (h *IntHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

// hasCommonElement 检查两个有序数组是否有共同元素
func hasCommonElement(arr1, arr2 []int) bool {
	i, j := 0, 0
	for i < len(arr1) && j < len(arr2) {
		if arr1[i] == arr2[j] {
			return true
		} else if arr1[i] < arr2[j] {
			i++
		} else {
			j++
		}
	}
	return false
}

// mergeMultipleArrays 合并多个有序数组为一个有序数组
func mergeMultipleArrays(arrays [][]int) []int {
	if len(arrays) == 0 {
		return []int{}
	}
	if len(arrays) == 1 {
		return arrays[0]
	}

	// 使用最小堆进行多路归并
	h := &IntHeap{}
	heap.Init(h)
	indices := make([]int, len(arrays))

	for i, arr := range arrays {
		if len(arr) > 0 {
			heap.Push(h, arr[0])
			indices[i] = 0
		}
	}

	var result []int
	for h.Len() > 0 {
		minVal := heap.Pop(h).(int)
		result = append(result, minVal)
		// 找到 minVal 来自哪个数组
		for i, arr := range arrays {
			if indices[i] < len(arr) && arr[indices[i]] == minVal {
				indices[i]++
				if indices[i] < len(arr) {
					heap.Push(h, arr[indices[i]])
				}
				break
			}
		}
	}
	return result
}

// mergeSortedArrays 主函数：合并有序数组列表
func mergeSortedArrays(arrays [][]int) [][]int {
	if len(arrays) == 0 {
		return [][]int{}
	}

	n := len(arrays)
	uf := NewUnionFind(n)

	// 检查所有数组对是否有共同元素，并合并
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if hasCommonElement(arrays[i], arrays[j]) {
				uf.Union(i, j)
			}
		}
	}

	// 根据并查集分组
	groups := make(map[int][][]int)
	for i := 0; i < n; i++ {
		root := uf.Find(i)
		groups[root] = append(groups[root], arrays[i])
	}

	// 合并每个组
	var result [][]int
	for _, group := range groups {
		merged := mergeMultipleArrays(group)
		result = append(result, merged)
	}

	return result
}

func main() {
	// 示例输入：根据输出反推，输入为两个数组 [2,4,6] 和 [6,8,10]
	arrays := [][]int{
		{2, 4, 6},
		{6, 8, 10},
	}

	// 调用合并函数
	mergedArrays := mergeSortedArrays(arrays)

	// 输出结果
	fmt.Println("合并后的数组:")
	for _, arr := range mergedArrays {
		fmt.Println(arr)
	}
}
