        }
        // 递归查找根节点，并进行路径压缩
        this.parent[node] = this.find(this.parent[node]);
        return this.parent[node];
    }

    // union 操作：合并两个节点（在此算法中可能不需要，但保留用于扩展）
    union(node1, node2) {
        let root1 = this.find(node1);
        let root2 = this.find(node2);
        if (root1 !== root2) {
            this.parent[root1] = root2;
        }
    }

    // 设置节点的父节点（用于构建树结构）
    setParent(node, parentNode) {
        this.parent[node] = parentNode;
    }

    // 获取所有节点
    getNodes() {
        return Object.keys(this.parent).map(Number);
    }
}

// 二叉树层序遍历函数，使用并查集
function levelOrderTraversalWithUnionFind(nodes, parentMap) {
    // 边界条件：空树
    if (!nodes || nodes.length === 0) {
        return [];
    }

    // 初始化并查集
    const uf = new UnionFind(nodes);
    // 设置每个节点的父节点
    for (let node of nodes) {
        if (parentMap[node] !== undefined) {
            uf.setParent(node, parentMap[node]);
        } else {
            uf.setParent(node, null); // 根节点的父节点为 null
        }
    }

    // 找到根节点（父节点为 null 的节点）
    let root = null;
    for (let node of nodes) {
        if (uf.parent[node] === null) {
            root = node;
            break;
        }
    }

    // 边界条件：单节点树
    if (root === null) {
        return nodes; // 如果没有明确根，返回所有节点（假设只有一个节点）
    }

    // 初始化队列和输出数组
    let queue = [root];
    let output = [];

    // BFS 遍历
    while (queue.length > 0) {
        let currentNode = queue.shift();
        output.push(currentNode);

        // 找到当前节点的所有子节点
        let children = [];
        for (let node of nodes) {
            if (uf.parent[node] === currentNode) {
                children.push(node);
            }
        }
        // 按值从小到大排序，确保左到右顺序
        children.sort((a, b) => a - b);
        // 将子节点入队
        for (let child of children) {
            queue.push(child);
        }
    }

    return output;
}

// 示例使用
const nodes = [2, 4, 6, 8, 10];
const parentMap = {
    2: null, // 根节点
    4: 2,
    6: 2,
    8: 4,
    10: 4
};

const result = levelOrderTraversalWithUnionFind(nodes, parentMap);
console.log(result); // 输出: [2, 4, 6, 8, 10]
```

### 算法说明
- **并查集的作用**：在此算法中，并查集主要用于存储和快速查找节点的父节点关系。`find` 操作用于验证根节点，但核心遍历仍依赖队列。
- **子节点查找**：由于并查集只存储父节点指针，算法通过遍历所有节点来找到当前节点的子节点。时间复杂度为 O(n²)，但适用于小规模数据。对于大规模数据，建议预处理子节点列表以提高效率。
- **边界条件**：代码已处理空树和单节点树的情况。
- **输出验证**：对于输入 `nodes = [2, 4, 6, 8, 10]` 和 `parentMap`，算法输出 `[2, 4, 6, 8, 10]`，与您的输出一致。

