        if (s < 0 || s >= V) {
            throw new IllegalArgumentException("起点索引无效");
        }

        boolean[] visited = new boolean[V];
        int[] distance = new int[V];
        int[] parent = new int[V];

        // 初始化数组
        for (int i = 0; i < V; i++) {
            visited[i] = false;
            distance[i] = -1; // 未访问
            parent[i] = -1;
        }

        Queue<Integer> queue = new LinkedList<>();
        visited[s] = true;
        distance[s] = 0;
        queue.add(s);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    distance[v] = distance[u] + 1;
                    parent[v] = u;
                    queue.add(v);
