# 使用跳表实现反转链表

我将实现一个跳表（Skip List）数据结构，并添加反转功能。反转操作通过反转跳表的每一层链表来实现，时间复杂度为 O(n log n)，符合要求。

## 实现思路

1. **跳表节点结构**：每个节点包含数据和多个指向下一层的指针。
2. **跳表类**：管理跳表的头节点、最大层数、概率因子等。
3. **反转方法**：遍历跳表的每一层，反转该层的链表。
4. **测试用例**：验证反转前后跳表的状态。

## C++ 代码实现

```cpp
#include <iostream>
#include <cstdlib>
#include <ctime>
#include <vector>

using namespace std;

// 跳表节点模板类
template <typename T>
class SkipListNode {
public:
    T data;
    vector<SkipListNode*> next; // 每个节点的多个next指针
    int level; // 节点的层数

    // 构造函数
    SkipListNode(T data, int level) : data(data), level(level) {
        next.resize(level, nullptr);
    }
};

// 跳表模板类
template <typename T>
class SkipList {
private:
    SkipListNode<T>* head; // 头节点
    int max_level; // 最大层数
    float probability; // 概率因子
    int node_count; // 节点数量

public:
    // 构造函数
    SkipList(int max_level = 16, float probability = 0.5) 
        : max_level(max_level), probability(probability), node_count(0) {
        head = new SkipListNode<T>(T(), max_level); // 头节点层数为max_level
        srand(time(0)); // 初始化随机种子
    }

    // 随机生成层数
    int randomLevel() {
        int level = 1;
        while (rand() < probability * RAND_MAX && level < max_level) {
            level++;
        }
        return level;
    }

    // 插入节点
    void insert(T data) {
        SkipListNode<T>* newNode = new SkipListNode<T>(data, randomLevel());
        SkipListNode<T>* current = head;
        vector<SkipListNode*> update(max_level, nullptr);

        // 找到插入位置
        for (int i = max_level - 1; i >= 0; i--) {
            while (current->next[i] != nullptr && current->next[i]->data < data) {
                current = current->next[i];
            }
            update[i] = current;
        }

        // 插入新节点
        for (int i = 0; i < newNode->level; i++) {
            newNode->next[i] = update[i]->next[i];
            update[i]->next[i] = newNode;
        }
        node_count++;
    }

    // 搜索节点
    bool search(T data) {
        SkipListNode<T>* current = head;
        for (int i = max_level - 1; i >= 0; i--) {
            while (current->next[i] != nullptr && current->next[i]->data < data) {
                current = current->next[i];
            }
        }
        current = current->next[0];
        return current != nullptr && current->data == data;
    }

    // 反转跳表
    void reverse() {
        // 对于每一层，反转该层的链表
        for (int i = 0; i < max_level; i++) {
            SkipListNode<T>* prev = nullptr;
            SkipListNode<T>* current = head->next[i];
            while (current != nullptr) {
                SkipListNode<T>* next = current->next[i];
                current->next[i] = prev;
                prev = current;
                current = next;
            }
            head->next[i] = prev;
        }
    }

    // 打印跳表（用于测试）
    void display() {
        for (int i = max_level - 1; i >= 0; i--) {
            cout << "Level " << i << ": ";
            SkipListNode<T>* current = head->next[i];
            while (current != nullptr) {
                cout << current->data << " ";
                current = current->next[i];
            }
            cout << endl;
        }
    }

    // 获取节点数量
    int getNodeCount() {
        return node_count;
    }
};

// 测试用例
int main() {
    SkipList<int> skipList;

    // 测试用例1: 插入节点并反转
    cout << "=== 测试用例1: 基本插入和反转 ===" << endl;
