package main

import (
	"container/heap"
	"fmt"
)

// 定义链表节点结构
type ListNode struct {
	Val  int
	Next *ListNode
}

// 定义最小堆类型（用于存储链表节点值）
type MinHeap []int

// 实现 heap.Interface 接口
func (h MinHeap) Len() int { return len(h) }
func (h MinHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h MinHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

// Push 方法用于向堆中添加元素
func (h *MinHeap) Push(x interface{}) {
	*h = append(*h, x.(int))
}

// Pop 方法用于从堆中移除并返回最小元素
func (h *MinHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

// 函数：使用堆排序对链表进行排序
func sortList(head *ListNode) *ListNode {
	if head == nil {
		return nil
	}

	// 创建最小堆
	h := &MinHeap{}
	heap.Init(h)

	// 遍历链表，将节点值推入堆中
	current := head
	for current != nil {
		heap.Push(h, current.Val)
		current = current.Next
	}

	// 从堆中弹出排序后的值，重建链表
	dummy := &ListNode{}
	current = dummy
	for h.Len() > 0 {
		val := heap.Pop(h).(int)
		current.Next = &ListNode{Val: val}
		current = current.Next
	}

	return dummy.Next
}

// 辅助函数：打印链表
func printList(head *ListNode) {
	current := head
	for current != nil {
		fmt.Print(current.Val)
		if current.Next != nil {
			fmt.Print(" -> ")
		}
		current = current.Next
	}
	fmt.Println()
}

func main() {
	// 构建输入链表: [10,8,6,4,2]
	head := &ListNode{Val: 10}
	head.Next = &ListNode{Val: 8}
	head.Next.Next = &ListNode{Val: 6}
	head.Next.Next.Next = &ListNode{Val: 4}
	head.Next.Next.Next.Next = &ListNode{Val: 2}

	fmt.Println("输入链表:")
	printList(head)

	// 对链表进行排序
	sortedHead := sortList(head)

	fmt.Println("排序后链表:")
	printList(sortedHead)
}
```

