// 定义链表节点
struct ListNode {
    int val;
    struct ListNode *next;
};

// 1. 获取链表长度
int getLength(struct ListNode *head) {
    int len = 0;
    while (head) {
        len++;
        head = head->next;
    }
    return len;
}

// 2. 二分查找定位中点（这里返回指向中点的指针）
struct ListNode* findMiddle(struct ListNode *head, int len) {
    int mid = len / 2;           // 中点下标
    struct ListNode *cur = head;
    for (int i = 0; i < mid; ++i) {
        cur = cur->next;
    }
    return cur;                  // 返回中点节点
}

// 3. 迭代反转整个链表
struct ListNode* reverseList(struct ListNode *head) {
    struct ListNode *prev = NULL;
    struct ListNode *curr = head;
    while (curr) {
        struct ListNode *next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;                 // 新的头结点
}

// 主函数
struct ListNode* reverseLinkedList(struct ListNode *head) {
    int n = getLength(head);          // 求长度
    // 这里可以调用 findMiddle 进行二分定位（可选），随后直接整体反转
    return reverseList(head);         // 整体反转
}
```

