**二、完整 Rust 实现（包含边界处理）**

```rust
// src/main.rs

use std::cmp::PartialOrd;
use std::collections::{HashMap, HashSet};

/// 二叉搜索树节点
struct Node<T> {
    value: T,
    left: Option<Box<Node<T>>>,
    right: Option<Box<Node<T>>>,
}

/// 二叉搜索树（BST）
/// 仅实现最基础的插入与查找，满足“两数之和”需求即可。
struct BST<T> {
    root: Option<Box<Node<T>>>,
}

impl<T: PartialOrd + Clone> BST<T> {
    /// 创建一个空的 BST
    fn new() -> Self {
        BST { root: None }
    }

    /// 插入元素（允许重复元素放在左子树）
    fn insert(&mut self, value: T) {
        let new_node = Box::new(Node {
            value: value.clone(),
            left: None,
            right: None,
        });

        match self.root {
            None => self.root = Some(new_node),
            Some(ref mut root) => {
                let mut cur = root;
                loop {
                    if value <= cur.value {
                        match cur.left {
                            None => {
                                cur.left = Some(new_node);
                                break;
                            }
                            Some(ref mut left) => cur = left,
                        }
                    } else {
                        match cur.right {
                            None => {
                                cur.right = Some(new_node);
                                break;
                            }
                            Some(ref mut right) => cur = right,
                        }
                    }
                }
            }
        }
    }

    /// 查找元素是否存在于 BST 中
    fn search(&self, value: &T) -> bool {
        let mut cur = &self.root;
        while let Some(ref node) = *cur {
            if value == &node.value {
                return true;
            } else if value < &node.value {
                cur = &node.left;
            } else {
                cur = &node.right;
            }
        }
        false
    }
}

/// 使用 BST 解决两数之和，返回所有能够组成目标值的 **唯一数字**（已排序）。
/// 若不存在任何合法对，则返回空向量。
fn two_sum_with_bst(arr: &[i32], target: i32) -> Vec<i32> {
    // 边界：数组长度不足 2 直接返回空
    if arr.len() < 2 {
        return vec![];
    }

    // 1. 把数组元素全部插入 BST
    let mut bst = BST::new();
    for &v in arr {
        bst.insert(v);
    }

    // 2. 统计每个数字的出现次数（用于处理 x == target‑x 的情况）
    let mut freq = HashMap::new();
    for &v in arr {
        *freq.entry(v).or_insert(0) += 1;
    }

    // 3. 查找所有合法对，使用 HashSet 去重
    let mut pair_set: HashSet<(i32, i32)> = HashSet::new();

    for &x in arr {
        let y = target - x;
        if bst.search(&y) {
            if x == y {
                // 需要 x 至少出现两次
                if let Some(&cnt) = freq.get(&x) {
                    if cnt >= 2 {
                        let pair = (x, y); // x == y，直接插入
                        pair_set.insert(pair);
                    }
                }
            } else {
                // 为防止 (a,b) 与 (b,a) 重复，只在 x <= y 时插入
                let pair = if x <= y { (x, y) } else { (y, x) };
                pair_set.insert(pair);
            }
        }
    }

    // 4. 收集所有出现过的唯一数字
    let mut unique = HashSet::new();
    for (a, b) in pair_set {
        unique.insert(a);
        unique.insert(b);
    }

    // 5. 排序返回
    let mut result: Vec<i32> = unique.into_iter().collect();
    result.sort();
    result
}

fn main() {
    // 示例：输入数组 [2,4,6,8,10]，目标值 12
    let arr = vec![2, 4, 6, 8, 10];
    let target = 12;

    let ans = two_sum_with_bst(&arr, target);
    println!("{:?}", ans); // 输出: [2, 4, 6, 8, 10]
}

// ------------------- 单元测试 -------------------
