const edges = [
  { u: 1, v: 2, w: 2 },
  { u: 2, v: 3, w: 4 },
  { u: 3, v: 4, w: 6 },
  { u: 4, v: 5, w: 8 },
  { u: 5, v: 6, w: 10 },
];

// 查询（a, b）—— 要求最小瓶颈路
const queries = [
  { a: 1, b: 2 }, // 第一次连通在 w = 2
  { a: 1, b: 3 }, // 第一次连通在 w = 4
  { a: 1, b: 4 }, // 第一次连通在 w = 6
  { a: 1, b: 5 }, // 第一次连通在 w = 8
  { a: 1, b: 6 }, // 第一次连通在 w = 10
];
```

### 4.3 运行代码

```js
