**实现思路**  
- 用 **哈希表（`map`）** 保存图的邻接表：`map[int]map[int]int`，即 `from → (to → weight)`。  
- 使用 **Dijkstra + 二叉堆（`container/heap`）** 求单源最短路。堆中保存当前仍未处理的顶点及其当前最短距离，  
  每次 `pop` 出距离最小的顶点进行松弛。  
- 用两张 `map` 保存中间结果：  
  - `dist map[int]int` – 已知的最短距离（`dist[v]` 为 `start → v` 的最短距离）  
  - `prev map[int]int` – 前驱顶点，用于在结束后重建路径。  
- 整个过程的复杂度是 `O((V+E)·logV)`，在 `E = O(V)`（即稀疏图）时即为 `O(V log V)`，满足 `O(n log n)` 的要求。

下面给出完整的实现（Go 1.18+，使用泛型会让代码更通用，这里为直观使用 `int` 作为顶点 ID）：

```go
package main

import (
	"container/heap"
	"errors"
	"fmt"
)

// ---------- 1. 邻接表 ----------
// graph[v] 保存从 v 出发的所有相邻边 (to -> weight)
// 为了方便使用，这里使用 map[int]map[int]int，即哈希表嵌套哈希表
type Graph map[int]map[int]int

// AddEdge 添加一条有向边 (u -> v，权重 w)
// 如果需要无向图，只要调用两次 AddEdge 即可
func (g Graph) AddEdge(u, v, w int) {
	if g[u] == nil {
		g[u] = make(map[int]int)
	}
	g[u][v] = w
}

// ---------- 2. 堆实现 (Dijkstra 需要) ----------
type item struct {
	id   int   // 顶点编号
	dist int   // 当前已知的最短距离
	index int  // 在 heap 中的下标，供 heap.Interface 的 Update 使用
}

// priorityQueue 实现 container/heap 接口
type priorityQueue []*item

func (pq priorityQueue) Len() int { return len(pq) }

func (pq priorityQueue) Less(i, j int) bool {
	// 距离越小越先弹出
	return pq[i].dist < pq[j].dist
}

func (pq priorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].index = i
	pq[j].index = j
}

func (pq *priorityQueue) Push(x interface{}) {
	it := x.(*item)
	it.index = len(*pq)
	*pq = append(*pq, it)
}

func (pq *priorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	it := old[n-1]
	*pq = old[0 : n-1]
	return it
}

// ---------- 3. Dijkstra ----------
var (
	ErrNoPath   = errors.New("no path from start to end")
	ErrNegative = errors.New("graph contains negative weight (not supported)")
)

// ShortestPath 返回 start → end 的最短路径长度、路径（包含起终点）以及可能错误
// 若不可达则返回 ErrNoPath；若图中出现负权则返回 ErrNegative
func ShortestPath(g Graph, start, end int) (int, []int, error) {
	// 初始化
	dist := make(map[int]int) // 最短距离表
	prev := make(map[int]int) // 前驱表
	pq := make(priorityQueue, 0)
	heap.Init(&pq)

	// 把起点放入堆，距离为 0
	dist[start] = 0
	heap.Push(&pq, &item{id: start, dist: 0})

	// 用于快速判断某顶点是否已经在堆中（防止重复入堆）
	inQueue := make(map[int]bool)
	inQueue[start] = true

	for pq.Len() > 0 {
		// 弹出当前距离最小的顶点
		curr := heap.Pop(&pq).(*item)
		inQueue[curr.id] = false

		// 已经得到更短的距离（说明之前有更短的入堆），直接跳过
		if curr.dist != dist[curr.id] {
			continue
		}

		// 到达终点，构造路径并返回
		if curr.id == end {
			return curr.dist, reconstructPath(prev, start, end), nil
		}

		// 遍历出边
		for to, w := range g[curr.id] {
			if w < 0 {
				// Dijkstra 不支持负权
				return -1, nil, ErrNegative
			}
			nd := curr.dist + w
			if d, ok := dist[to]; !ok || nd < d {
				dist[to] = nd
				prev[to] = curr.id
				// 如果已经在堆中，则更新距离
				if inQueue[to] {
					// 这里需要遍历堆找到对应的 item 并更新，效率不高
					// 为简化实现，直接重新 push（堆中会出现两条相同顶点记录，
					// 弹出时会因为 dist 不等于最新的 dist 而被过滤掉）
				}
				heap.Push(&pq, &item{id: to, dist: nd})
				inQueue[to] = true
			}
		}
	}
	// 循环结束仍未到达终点，说明不可达
	return -1, nil, ErrNoPath
}

// reconstructPath 根据 prev 表重新构造从 start 到 end 的完整路径
func reconstructPath(prev map[int]int, start, end int) []int {
	path := []int{}
	cur := end
	for cur != start {
		path = append(path, cur)
		p, ok := prev[cur]
		if !ok {
			// 没有前驱，说明不可达（实际上已经在 ShortestPath 判错）
			return nil
		}
		cur = p
	}
	path = append(path, start)
	// 反转
	for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
		path[i], path[j] = path[j], path[i]
	}
	return path
}

// ---------- 4. 示例 & 单元测试 ----------
func main() {
	// 构造一个简单的有向图
	g := make(Graph)
	edges := [][3]int{
		{0, 1, 4},
		{0, 2, 1},
		{1, 2, 2},
		{1, 3, 5},
		{2, 1, 2},
		{2, 3, 8},
		{2, 4, 10},
		{3, 4, 2},
		{3, 5, 6},
		{4, 5, 3},
	}
	for _, e := range edges {
		g.AddEdge(e[0], e[1], e[2])
	}

	// 测试几条路径
	tests := [][2]int{{0, 5}, {0, 4}, {2, 3}}
	for _, tcase := range tests {
		start, end := tcase[0], tcase[1]
		dist, path, err := ShortestPath(g, start, end)
		if err != nil {
			fmt.Printf("start=%d, end=%d -> error: %v\n", start, end, err)
		} else {
			fmt.Printf("start=%d, end=%d -> distance=%d, path=%v\n", start, end, dist, path)
		}
	}
}

