**思路概述**  
本题要求使用 **堆（优先队列）** 来求解「最长回文子串」。一种直观的做法是：

1. 把所有可能的回文中心（或中心对）看成**候选区间** `(l, r)`（闭区间），并把它们放入一个 **最大堆**（长度最长的先弹出）。  
2. 每次弹出当前堆顶（即当前已知的「最长」候选区间），检查它是否为回文：  
   - 若是，则直接返回该子串——它一定是全局最长的回文子串（因为堆按长度降序弹出）。  
   - 若不是，则尝试向两侧扩展得到更大的区间 `(l‑1, r+1)`（前提是两侧字符相等并且该新区间尚未被访问过），并把新区间加入堆中。  
3. 为防止重复扩展，使用 `unordered_set`（或 `std::set`）把已经放入堆的区间记录下来。

该算法在最坏情况下会生成 `O(n²)` 个区间，时间复杂度约为 `O(n² log n)`，空间复杂度也是 `O(n²)`。对教学和中等规模（几千字符以内）的输入已经足够。  

下面给出完整的 C++ 实现（使用 C++17 标准），并附带若干边界测试用例。

---

## 代码实现

```cpp
/******************************************************************
 *  File: longest_palindromic_substring_heap.cpp
 *  Description: 使用最大堆（优先队列）求最长回文子串
 *  Author: Emind·智脑 (亦梓科技)
 *  Compile: g++ -std=c++17 -O2 -Wall longest_palindromic_substring_heap.cpp
 ******************************************************************/

#include <bits/stdc++.h>
using namespace std;

/* 把区间 (l, r) 编码为 64 位整数，便于放入 unordered_set */
static inline long long encode(int l, int r) {
    return (static_cast<long long>(l) << 32) | static_cast<unsigned int>(r);
}

/* 堆中保存的节点结构 */
struct Node {
    int l, r;   // 区间左右端点（闭区间）
    int len;    // 子串长度 r-l+1
    // 为了让 priority_queue 默认为最大堆，需要自定义 operator<
    bool operator<(const Node& other) const {
        return len < other.len;   // length 大的在 top
    }
};

/* 判断 s[l..r] 是否为回文（暴力检查） */
static bool isPalindrome(const string& s, int l, int r) {
    while (l < r) {
        if (s[l++] != s[r--]) return false;
    }
    return true;
}

/**
 * @brief 求最长回文子串（使用堆）
 * @param s 输入字符串
 * @return 最长回文子串（若有多个，返回最早出现的那个）
 */
string longestPalindrome(const string& s) {
    int n = static_cast<int>(s.size());
    if (n == 0) return "";
    if (n == 1) return s;

    // 访问集合，防止重复入堆
    unordered_set<long long> visited;
    visited.reserve(n * n / 2); // 简单预分配

    // 最大堆
    priority_queue<Node> pq;

    // 1. 把所有单字符区间 (i,i) 入堆
    for (int i = 0; i < n; ++i) {
        Node node{i, i, 1};
        pq.push(node);
        visited.insert(encode(i, i));
    }

    // 2. 把所有相邻相等字符构成的偶回文区间 (i,i+1) 入堆
    for (int i = 0; i + 1 < n; ++i) {
        if (s[i] == s[i + 1]) {
            Node node{i, i + 1, 2};
            pq.push(node);
            visited.insert(encode(i, i + 1));
        }
    }

    // 3. 逐步弹出、检查、扩展
    while (!pq.empty()) {
        Node cur = pq.top(); pq.pop();

        // 先检查当前区间是否为回文
        if (isPalindrome(s, cur.l, cur.r)) {
            return s.substr(cur.l, cur.len);
        }

        // 若不是回文，尝试向两侧扩展
        if (cur.l > 0 && cur.r + 1 < n && s[cur.l - 1] == s[cur.r + 1]) {
            int nl = cur.l - 1;
            int nr = cur.r + 1;
            long long key = encode(nl, nr);
            if (!visited.count(key)) {
                visited.insert(key);
                pq.push(Node{nl, nr, cur.len + 2});
            }
        }
    }

    // 理论上不会出现找不到回文的情况（单字符已经在堆里），但以防万一
    return "";
}

/* ----------------------- 测试代码 ----------------------- */
int main() {
    // 辅助函数：打印测试结果
    auto test = [](const string& input, const string& expected) {
        string ans = longestPalindrome(input);
        cout << "Input:  \"" << input << "\"\n";
        cout << "Output: \"" << ans << "\"\n";
        cout << "Expect: \"" << expected << "\"\n";
        cout << (ans == expected ? "✅ PASS" : "❌ FAIL") << "\n\n";
    };

    // 1. 空串
    test("", "");

    // 2. 单字符
    test("a", "a");

    // 3. 全部相同
    test("aaaaa", "aaaaa");

    // 4. 偶数长度回文
    test("abba", "abba");

    // 5. 奇数长度回文
    test("aba", "aba");

    // 6. 既有奇数也有偶数，取最长的
    test("abacdfgdcaba", "aba");   // 第一个出现的最长回文是 "aba"

    // 7. 多个等长回文，返回先出现的
