        System.out.println("测试4: " + ans4 + " (期望: 2)");

        // ---------- 测试 5 ----------
        // 更长的路径
        List<String> dict5 = Arrays.asList(
                "aaaaa", "aaaab", "aaaba", "aaabb", "aabaa",
                "aabab", "aabba", "aabbb", "abaaa", "abaab",
                "ababa", "ababb", "abbaa", "abbab", "abbba",
                "abbbb", "baaaa", "baaab", "baaba", "baabb",
                "babaa", "babab", "babba", "babbb", "bbaaa",
                "bbaab", "bbaba", "bbabb", "bbbaa", "bbbab",
                "bbbba", "bbbbb"
        );
        int ans5 = solver.ladderLength("aaaaa", "bbbbb", dict5);
