下面给出一个 **完整、可直接运行的 Go 示例**，演示如何使用 **Trie（前缀树）** 把多个已排序的数组归并成一个大有序数组。  
在代码中我标注了 **常见的 Bug**（原实现容易出现的问题）以及对应的 **修复方法**，并对所有边界情况（空数组、仅有一个元素、负数、重复元素等）做了处理。

> **如果你手头已有原来的代码**，请把下面的“常见 Bug & 修复”对照检查；如果你想直接使用，直接把整个 `merge.go` 复制到你的项目中即可。

---

## 1. 常见 Bug（以及为什么会出现）

| # | 常见 Bug | 产生原因 | 修复方式 |
|---|----------|----------|----------|
| 1 | **没有对数字进行定长填充** | 直接把 `int` 转成字符串（如 `fmt.Sprint(n)`），导致 `"2"` > `"10"`（字典序），从而输出顺序错误。 | 把每个整数统一转为 **定长、零填充** 的字符串（例如负数先加偏移量再转成 10 位无符号十进制）。 |
| 2 | **未处理负数** | 负数的 `-` 符号会破坏“定长数字”规则，导致排序错乱。 | 将所有整数映射到 **uint32**（`n + 2^31`），再统一转成 10 位字符串。 |
| 3 | **重复元素只保留一次** | 只在叶子结点保存 `bool`，导致相同数值被丢弃。 | 在叶子结点保存 **出现次数**（`cnt int`），遍历时输出 `cnt` 次。 |
| 4 | **空数组或全部为空** | 插入阶段没有对 `nil` 数组做保护，导致 panic。 | 在插入前检查 `len(arr) == 0`，直接跳过。 |
| 5 | **递归层数过深**（数组元素非常多） | 使用递归实现 `InOrder` 有可能会堆栈溢出。 | 改用 **显式栈**（`[]*TrieNode`）进行深度优先遍历，或者把递归限制在合理规模（Go 默认栈足够大，一般不会溢出，但显式栈更安全）。 |

下面的代码已经全部修复了上述 1‑5 点。

---

## 2. 完整代码（merge.go）

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// ---------- 1. Trie 定义 ----------
const (
	DigitCount = 10 // 10 位十进制（足够覆盖 int32 范围）
)

// TrieNode 表示前缀树的一个结点
type TrieNode struct {
	children [DigitCount]*TrieNode // 0‑9 十个分支
	cnt      int                   // 以该结点为结尾的数出现了多少次（叶子结点的计数）
}

// Trie 公开的前缀树结构
type Trie struct {
	root *TrieNode
}

// NewTrie 初始化一棵空 Trie
func NewTrie() *Trie {
	return &Trie{root: &TrieNode{}}
}

// ---------- 2. 辅助函数：整数 <-> 定长字符串 ----------
const (
	// 2^31，用于把有符号 int32 映射到无符号 uint32
	offset = uint32(1 << 31)
	// 每个数字固定 10 位十进制（0~9），加上可能的负号我们已经在映射阶段去掉了
	digitFmt = "%010d"
)

// toFixedString 把有符号 int 转换为定长、无符号、零填充的十进制字符串
func toFixedString(n int) string {
	// 先把有符号整数转为 uint32（加上偏移量），保证全部是非负数
	u := uint32(n) + offset
	return fmt.Sprintf(digitFmt, u)
}

// fromFixedString 把定长字符串还原为原始 int（只在最终输出时使用）
func fromFixedString(s string) int {
	u, _ := strconv.ParseUint(s, 10, 32)
	return int(u) - int(offset)
}

// ---------- 3. 插入 ----------
// Insert 将一个已排序的数组中的所有元素插入 Trie
// 注意：数组本身必须是升序的，插入顺序不影响最终结果
func (t *Trie) Insert(arr []int) {
	if len(arr) == 0 {
		return
	}
	node := t.root
	for _, v := range arr {
		fixed := toFixedString(v) // 统一成 10 位字符串
		for _, ch := range fixed {
			d := int(ch - '0')
			if node.children[d] == nil {
				node.children[d] = &TrieNode{}
			}
			node = node.children[d]
		}
		// 到达数字的末尾，计数 +1
		node.cnt++
	}
}

// ---------- 4. 归并（遍历） ----------
// InOrder 按递增顺序返回所有已经插入的整数
// 使用显式栈避免递归导致的栈溢出
func (t *Trie) InOrder() []int {
	var result []int
	// 栈中保存当前结点以及下一个要访问的数字索引（0‑9）
	type frame struct {
		node   *TrieNode
		digit  int // 下一个要遍历的子分支（0‑9）
	}
	stack := []frame{{node: t.root, digit: 0}}

	for len(stack) > 0 {
		// 取出栈顶帧
		lf := len(stack) - 1
		cur := stack[lf].node
		idx := stack[lf].digit

		if idx == 0 && cur.cnt > 0 {
			// 当前结点是一个数字的结束位置，输出 cnt 次
			for i := 0; i < cur.cnt; i++ {
				result = append(result, fromFixedString(buildPath(cur)))
			}
		}

		if idx < DigitCount {
			// 继续遍历子节点
			stack[lf].digit = idx + 1 // 下次再回到当前结点时，直接跳到下一个分支
			if child := cur.children[idx]; child != nil {
				// 把子结点压栈，下一次从 digit=0 开始
				stack = append(stack, frame{node: child, digit: 0})
			}
		} else {
			// 所有子分支都已遍历，弹出
			stack = stack[:lf]
		}
	}
	return result
}

// buildPath 递归回溯得到从根到当前叶子结点的数字字符串（仅供调试或小数据量使用）
// 为降低递归深度，这里使用简单的递归；因为路径长度固定为 10，递归栈非常浅
func buildPath(node *TrieNode) string {
	var sb strings.Builder
	var dfs func(*TrieNode)
	dfs = func(n *TrieNode) {
		for d := DigitCount - 1; d >= 0; d-- { // 从最高位到低位
			if n.children[d] != nil {
				sb.WriteByte('0' + byte(d))
				dfs(n.children[d])
				return
			}
		}
	}
	dfs(node)
	return sb.String()
}

// ---------- 5. 对外接口 ----------
// MergeSortedArrays 接受若干已排序的 int 切片，返回一个完整的有序切片
func MergeSortedArrays(arrays ...[]int) []int {
	trie := NewTrie()
	for _, arr := range arrays {
		trie.Insert(arr) // 插入过程已经保证了顺序无关性
	}
	return trie.InOrder()
}

// ---------- 6. 示例 + 简单测试 ----------
func main() {
	// 示例 1：基本合并
	arr1 := []int{1, 3, 5, 7}
	arr2 := []int{2, 4, 6, 8}
	arr3 := []int{0, 9, 10, 11}
	res := MergeSortedArrays(arr1, arr2, arr3)
	fmt.Println("示例 1（基本合并）:", res)

	// 示例 2：包含负数和重复
	arr4 := []int{-5, -3, -1, 3, 3, 5}
	arr5 := []int{-4, -2, 0, 3, 4}
	res2 := MergeSortedArrays(arr4, arr5)
	fmt.Println("示例 2（含负数、重复）:", res2)

	// 示例 3：空数组
	arr6 := []int{}
	arr7 := []int{1, 2, 3}
	res3 := MergeSortedArrays(arr6, arr7)
	fmt.Println("示例 3（有空数组）:", res3)

	// 示例 4：全部为空
	res4 := MergeSortedArrays([]int{}, []int{})
	fmt.Println("示例 4（全空）:", res4)

	// 示例 5：大规模数据（仅示例，实际使用请自行对拍性能）
	// 这里不打印，仅检测是否 panic
	big := make([]int, 1_000_000)
	for i := range big {
		big[i] = i - 500_000 // -500000 ~ 499999
	}
	_ = MergeSortedArrays(big, big) // 两份同样的超大数组
	fmt.Println("示例 5（大数据）: 完成（未 panic）")

	// 若想交互式查看结果，可使用下面的简易 REPL
	runRepl()
}

// ---------- 7. 小型交互式 REPL（可选） ----------
func runRepl() {
	fmt.Println("\n--- 简易 REPL（输入每行一个已排序数组，以空行结束）---")
	sc := bufio.NewScanner(os.Stdin)
	var arrays [][]int
	for {
		fmt.Print("> ")
		if !sc.Scan() {
			break
		}
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			// 空行结束输入
			break
		}
		// 解析一行整数（以空格或逗号分隔）
		fields := strings.FieldsFunc(line, func(r rune) bool {
			return r == ' ' || r == ','
		})
		arr := make([]int, 0, len(fields))
		for _, f := range fields {
			if v, err := strconv.Atoi(f); err == nil {
				arr = append(arr, v)
			}
		}
		arrays = append(arrays, arr)
	}
	if len(arrays) == 0 {
		fmt.Println("未输入任何数组")
		return
	}
	res := MergeSortedArrays(arrays...)
	fmt.Printf("合并结果：%v\n", res)
}
```

### 代码说明（对照常见 Bug）

1. **定长填充**  
   - `toFixedString` 把每个 `int` 加上 `2^31` 偏移后转成 10 位十进制字符串（`%010d`），保证所有数字同宽。  
   - 这样 **字典序** 即 **数值序**，直接遍历 0‑9 子节点即可得到递增序列。

2. **负数处理**  
   - 负数在映射到 `uint32`（`uint32(n)+offset`）后全部变为非负整数，后续处理不再区分符号。

3. **重复元素**  
   - `TrieNode.cnt` 记录该数字出现的次数。遍历时 `for i := 0; i < cur.cnt; i++` 完整输出。

4. **空数组**  
   - `Insert` 在 `len(arr)==0` 时直接返回，不会 panic。

5. **递归层数**  
   - `InOrder` 使用显式栈 `[]frame`，深度最多为数字位数（10），即使百万级元素也不会爆栈。

6. **其它细节**  
   - `buildPath` 仅用于把叶子结点恢复成原始字符串（调试/小数据），在 `InOrder` 中我们通过 `fromFixedString` 直接把路径转换为原始整数，避免了额外的递归。

---

